     }\n    }\n}",
        "focus" to "@Composable\nprivate fun StyleFocus(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var remaining by rememberSaveable { mutableIntStateOf(60) }\n    // Recreating this composition restores the remaining time in a paused state.\n    var running by remember { mutableStateOf(false) }\n    LaunchedEffect(interactive, running) {\n        if (!interactive || !running) return@LaunchedEffect\n        val deadline = System.nanoTime() + remaining * 1_000_000_000L\n        while (remaining > 0) {\n            delay(250L)\n            remaining = ((deadline - System.nanoTime() + 999_999_999L) / 1_000_000_000L).toInt().coerceAtLeast(0)\n        }\n        running = false\n    }\n    val fraction = (60 - remaining) / 60f\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(16.dp)) {\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = Alignment.CenterVertically) {\n            Text(\"STILL / 静室\", color = s.text, fontSize = 10.sp, letterSpacing = 2.sp,\n                fontFamily = FontFamily.Monospace, fontWeight = FontWeight.Bold)\n            Box(Modifier.size(8.dp).background(if (running) s.extra else s.text.copy(alpha = .25f), CircleShape))\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 14.dp), horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = Alignment.Bottom) {\n            Text(\"把时间\\n还给自己。\", color = s.text, fontFamily = FontFamily.Serif,\n                fontSize = 28.sp, lineHeight = 32.sp, modifier = Modifier.weight(1f))\n            Text(\"一件事\\n一个当下\", color = s.text.copy(alpha = .65f), fontSize = 10.sp,\n                lineHeight = 17.sp, textAlign = TextAlign.End, modifier = Modifier.padding(bottom = 4.dp))\n        }\n        BoxWithConstraints(Modifier.fillMaxWidth().padding(top = 10.dp)) {\n            val fontScale = LocalDensity.current.fontScale\n            if (maxWidth < (268 * fontScale).dp) {\n                Column(Modifier.fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally) {\n                    FocusHourglass(s, fraction, running, Modifier.widthIn(max = 180.dp).fillMaxWidth().height(130.dp))\n                    FocusClock(s, remaining, running, Modifier.fillMaxWidth().padding(top = 12.dp), centered = true)\n                }\n            } else {\n                Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {\n                    FocusHourglass(s, fraction, running, Modifier.weight(1f).height(130.dp))\n                    FocusClock(s, remaining, running, Modifier.weight(1f).padding(start = 12.dp))\n                }\n            }\n        }\n        Canvas(Modifier.fillMaxWidth().height(14.dp).padding(vertical = 5.dp)) {\n            repeat(30) { i ->\n                drawLine(if (i < fraction * 30) s.text else s.text.copy(alpha = .15f),\n                    Offset(size.width * i / 30, 0f), Offset(size.width * i / 30, size.height), 2.dp.toPx())\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 12.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            Button(onClick = {\n                if (remaining == 0) remaining = 60\n                running = !running\n            }, enabled = interactive, modifier = Modifier.weight(1f).heightIn(min = 48.dp),\n                shape = RoundedCornerShape(3.dp), colors = ButtonDefaults.buttonColors(\n                    containerColor = s.text, contentColor = s.bg,\n                    disabledContainerColor = s.text, disabledContentColor = s.bg)) {\n                Text(if (running) \"Ⅱ  暂停\" else if (remaining < 60 && remaining > 0) \"↗  继续专注\" else \"↗  开始专注\",\n                    fontSize = 12.sp)\n            }\n            TextButton(onClick = { running = false; remaining = 60 }, enabled = interactive,\n                modifier = Modifier.heightIn(min = 48.dp), shape = RoundedCornerShape(3.dp),\n                colors = ButtonDefaults.textButtonColors(contentColor = s.text, disabledContentColor = s.text)) {\n                Text(\"重置\", fontSize = 12.sp)\n            }\n        }\n    }\n}\n\n\n@Composable\nprivate fun FocusHourglass(s: CreativeStyleSpec, fraction: Float, running: Boolean, modifier: Modifier) {\n    Canvas(modifier.semantics { contentDescription = \"沙漏，专注进度 \${(fraction * 100).toInt()}%\" }) {\n        val left = size.width * .15f\n        val right = size.width * .85f\n        val top = size.height * .1f\n        val bottom = size.height * .9f\n        val glass = Path().apply {\n            moveTo(left, top)\n            cubicTo(left, size.height * .38f, center.x - 4.dp.toPx(), size.height * .41f, center.x - 4.dp.toPx(), center.y)\n            cubicTo(center.x - 4.dp.toPx(), size.height * .59f, left, size.height * .62f, left, bottom)\n            lineTo(right, bottom)\n            cubicTo(right, size.height * .62f, center.x + 4.dp.toPx(), size.height * .59f, center.x + 4.dp.toPx(), center.y)\n            cubicTo(center.x + 4.dp.toPx(), size.height * .41f, right, size.height * .38f, right, top)\n            close()\n        }\n        clipPath(glass) {\n            drawRect(s.text.copy(alpha = .06f))\n            val upper = size.height * (.14f + fraction * .35f)\n            drawRect(s.text, Offset(left, upper), Size(right - left, (center.y - upper).coerceAtLeast(0f)))\n            val sand = Path().apply {\n                moveTo(left, bottom)\n                lineTo(left, bottom - fraction * size.height * .1f)\n                quadraticTo(center.x, bottom - fraction * size.height * .58f, right, bottom - fraction * size.height * .1f)\n                lineTo(right, bottom)\n                close()\n            }\n            drawPath(sand, s.text)\n            if (running) {\n                repeat(7) { i ->\n                    drawCircle(s.text, 1.dp.toPx(), Offset(center.x, center.y + i * 6.dp.toPx()))\n                }\n            }\n        }\n        drawPath(glass, s.text, style = Stroke(1.2.dp.toPx()))\n        drawLine(s.text, Offset(left - 6.dp.toPx(), top), Offset(right + 6.dp.toPx(), top), 4.dp.toPx(), StrokeCap.Round)\n        drawLine(s.text, Offset(left - 6.dp.toPx(), bottom), Offset(right + 6.dp.toPx(), bottom), 4.dp.toPx(), StrokeCap.Round)\n    }\n}\n\n@Composable\nprivate fun FocusClock(\n    s: CreativeStyleSpec,\n    remaining: Int,\n    running: Boolean,\n    modifier: Modifier,\n    centered: Boolean = false,\n) {\n    BoxWithConstraints(modifier) {\n        val fontScale = LocalDensity.current.fontScale\n        // Four monospaced glyphs must remain fully visible even with large accessibility text.\n        val timerSize = minOf(45f, maxWidth.value / fontScale / 2.5f)\n        Column(Modifier.fillMaxWidth(), horizontalAlignment = if (centered) Alignment.CenterHorizontally else Alignment.Start) {\n            Text(\"\${remaining / 60}:\${(remaining % 60).toString().padStart(2, '0')}\", color = s.text,\n                fontSize = timerSize.sp, lineHeight = (timerSize * 1.14f).sp, letterSpacing = (-2).sp,\n                fontFamily = FontFamily.Monospace, fontWeight = FontWeight.Light, maxLines = 1, softWrap = false,\n                modifier = Modifier.semantics { contentDescription = \"剩余 \$remaining 秒\" })\n            Text(when { remaining == 0 -> \"完成了，深呼吸。\"; running -> \"此刻，只做一件事\"; remaining < 60 -> \"暂停，时间为你停留\"; else -> \"准备好了就开始\" },\n                color = s.text.copy(alpha = .7f), fontSize = 10.sp, lineHeight = 15.sp,\n                textAlign = if (centered) TextAlign.Center else TextAlign.Start,\n                modifier = Modifier.padding(top = 5.dp))\n            Text(\"60 秒体验 · 专注仪式\", color = s.text.copy(alpha = .6f), fontSize = 8.sp,\n                modifier = Modifier.padding(top = 13.dp))\n        }\n    }\n}",
        "orbit" to "@Composable\nprivate fun StyleOrbit(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var playing by rememberSaveable { mutableStateOf(false) }\n    var track by rememberSaveable { mutableIntStateOf(0) }\n    val tracks = p.items.ifEmpty { listOf(\"Lunar drift\", \"Deep field\", \"Solar wind\") }\n    val title = tracks[track % tracks.size]\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(20.dp)) {\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n            Text(\"O R B I T / R A D I O\", color = s.text, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            Text(\"S—0\${track + 1}\", color = s.primary, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n        }\n        Box(Modifier.fillMaxWidth().height(224.dp)) {\n            Text(\"SPACE\\nTO FEEL.\", Modifier.align(Alignment.TopStart).padding(top = 20.dp),\n                color = s.text, fontSize = 35.sp, lineHeight = 33.sp, fontWeight = FontWeight.Black,\n                letterSpacing = (-1.5).sp)\n            Canvas(Modifier.fillMaxSize().semantics { contentDescription = \"倾斜的黑胶星球与环绕轨道\" }) {\n                val c = Offset(size.width * .59f, size.height * .61f)\n                val r = size.width * .24f\n                drawCircle(Brush.radialGradient(listOf(s.primary.copy(alpha = .14f), Color.Transparent), c, r * 1.8f), r * 1.8f, c)\n                rotate(-24f, c) {\n                    repeat(3) { n ->\n                        drawOval(s.primary.copy(alpha = .28f - n * .07f),\n                            Offset(c.x - r * (1.9f + n * .19f), c.y - r * (.63f + n * .14f)),\n                            Size(r * (3.8f + n * .38f), r * (1.26f + n * .28f)), style = Stroke(1.dp.toPx()))\n                    }\n                }\n                drawCircle(Brush.linearGradient(listOf(s.primary.copy(alpha = .82f), s.bg, s.bg), c - Offset(r, r), c + Offset(r, r)), r, c)\n                repeat(10) { n -> drawCircle(s.primary.copy(alpha = .11f), r * (.3f + n * .065f), c, style = Stroke(.7.dp.toPx())) }\n                drawCircle(s.primary, r * .19f, c)\n                drawCircle(s.bg, r * .05f, c)\n                rotate(-24f, c) {\n                    drawArc(s.primary, 8f, 154f, false, Offset(c.x - r * 1.9f, c.y - r * .63f), Size(r * 3.8f, r * 1.26f), style = Stroke(1.4.dp.toPx()))\n                    drawCircle(s.primary, 5.dp.toPx(), Offset(c.x + r * 1.77f, c.y + r * .22f))\n                }\n                val star = Offset(size.width * .92f, size.height * .19f)\n                drawLine(s.primary, star - Offset(0f, 6.dp.toPx()), star + Offset(0f, 6.dp.toPx()), 1.dp.toPx())\n                drawLine(s.primary, star - Offset(6.dp.toPx(), 0f), star + Offset(6.dp.toPx(), 0f), 1.dp.toPx())\n            }\n            Text(\"33⅓\\nRPM\", Modifier.align(Alignment.BottomStart).padding(bottom = 4.dp), color = s.text.copy(alpha = .55f),\n                fontSize = 9.sp, lineHeight = 12.sp, fontFamily = FontFamily.Monospace)\n            Text(\"SIDE \${if (track % 2 == 0) \"A\" else \"B\"}\", Modifier.align(Alignment.BottomEnd).padding(bottom = 4.dp),\n                color = s.text.copy(alpha = .55f), fontSize = 9.sp, fontFamily = FontFamily.Monospace)\n        }\n        Box(Modifier.fillMaxWidth().height(1.dp).background(s.text.copy(alpha = .18f)))\n        Row(Modifier.fillMaxWidth().padding(top = 14.dp), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f)) {\n                Text(title, color = s.text, fontSize = 22.sp, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = TextOverflow.Ellipsis)\n                Text(if (playing) \"PLAYING · 试听状态演示\" else \"AMBIENT SESSION · 01\", Modifier.padding(top = 4.dp),\n                    color = s.text.copy(alpha = .6f), fontSize = 9.sp, fontFamily = FontFamily.Monospace)\n            }\n            Box(Modifier.size(52.dp).clip(CircleShape).background(s.primary)\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = if (playing) \"暂停播放演示\" else \"开始播放演示\") { playing = !playing }\n                .semantics { contentDescription = if (playing) \"暂停播放演示\" else \"开始播放演示\"; stateDescription = if (playing) \"播放中\" else \"已暂停\" },\n                contentAlignment = Alignment.Center) {\n                Canvas(Modifier.size(19.dp)) {\n                    if (playing) {\n                        drawLine(s.bg, Offset(size.width * .3f, 1f), Offset(size.width * .3f, size.height - 1f), 4.dp.toPx())\n                        drawLine(s.bg, Offset(size.width * .75f, 1f), Offset(size.width * .75f, size.height - 1f), 4.dp.toPx())\n                    } else drawPath(Path().apply { moveTo(3.dp.toPx(), 0f); lineTo(size.width, center.y); lineTo(3.dp.toPx(), size.height); close() }, s.bg)\n                }\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 8.dp), verticalAlignment = Alignment.CenterVertically) {\n            Canvas(Modifier.weight(1f).height(24.dp)) {\n                repeat(44) { i ->\n                    val h = if (playing) (4 + ((i * 13 + track * 7) % 19)).dp.toPx() else (2 + ((i * 7 + track * 3) % 9)).dp.toPx()\n                    val x = i * size.width / 44\n                    drawLine(if (i < 16 + track * 5) s.primary else s.text.copy(alpha = .23f), Offset(x, center.y - h / 2), Offset(x, center.y + h / 2), 2.dp.toPx(), StrokeCap.Round)\n                }\n            }\n            Box(Modifier.padding(start = 12.dp).height(48.dp).widthIn(min = 64.dp)\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = \"切换下一首\") { track = (track + 1) % tracks.size }, contentAlignment = Alignment.Center) {\n                Text(\"NEXT ↗\", color = s.primary, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            }\n        }\n    }\n}",
        "spectrum" to "@Composable\nprivate fun StyleSpectrum(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var hue by rememberSaveable { mutableFloatStateOf(.48f) }\n    var wide by rememberSaveable { mutableStateOf(false) }\n    val tint = Color.hsv(190f + hue * 140f, .6f, 1f)\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(horizontal = 20.dp, vertical = 18.dp)) {\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.Top) {\n            Column {\n                Text(\"LIGHT / LAB\", color = s.text.copy(alpha = .65f), fontSize = 9.sp, letterSpacing = 2.sp, fontFamily = FontFamily.Monospace)\n                Text(\"折射之间\", Modifier.padding(top = 6.dp), color = s.text, fontSize = 27.sp, fontWeight = FontWeight.Light, letterSpacing = 2.sp)\n            }\n            Text(\"0\${if (wide) 2 else 1}\", color = s.text, fontSize = 42.sp, fontWeight = FontWeight.ExtraLight, letterSpacing = (-2).sp)\n        }\n        Box(Modifier.fillMaxWidth().height(217.dp).clip(RoundedCornerShape(2.dp))) {\n            Canvas(Modifier.fillMaxSize().semantics { contentDescription = \"由色相与扩散角度控制的三棱镜光束\" }) {\n                val prism = Offset(size.width * .5f, size.height * .47f)\n                val r = size.width * .23f\n                repeat(6) { i ->\n                    val y = size.height * (if (wide) .03f + i * .18f else .12f + i * .145f)\n                    val path = Path().apply {\n                        moveTo(prism.x + r * .24f, prism.y + r * .02f)\n                        lineTo(size.width * 1.05f, y)\n                        lineTo(size.width * 1.05f, y + size.height * .12f)\n                        close()\n                    }\n                    val beam = Color.hsv((185f + hue * 125f + i * 27) % 360f, .61f, 1f)\n                    drawPath(path, Brush.linearGradient(listOf(beam.copy(alpha = .9f), beam.copy(alpha = .05f)), prism, Offset(size.width, y)))\n                }\n                drawPath(Path().apply {\n                    moveTo(-10f, size.height * .42f); lineTo(prism.x - r * .4f, prism.y - r * .04f)\n                    lineTo(prism.x - r * .35f, prism.y + r * .07f); lineTo(-10f, size.height * .49f); close()\n                }, Brush.horizontalGradient(listOf(Color.White.copy(alpha = .03f), Color.White.copy(alpha = .8f))))\n                val triangle = Path().apply {\n                    moveTo(prism.x, prism.y - r); lineTo(prism.x + r * .91f, prism.y + r * .69f)\n                    lineTo(prism.x - r * .91f, prism.y + r * .69f); close()\n                }\n                drawPath(triangle, Brush.linearGradient(listOf(tint.copy(alpha = .18f), s.bg.copy(alpha = .9f), tint.copy(alpha = .27f)), prism - Offset(r, r), prism + Offset(r, r)))\n                drawPath(triangle, Brush.linearGradient(listOf(Color.White.copy(alpha = .9f), tint.copy(alpha = .35f), Color.White.copy(alpha = .7f))), style = Stroke(1.2.dp.toPx()))\n                drawLine(Color.White.copy(alpha = .27f), prism + Offset(0f, -r), prism + Offset(0f, r * .43f), 1.dp.toPx())\n                drawLine(Color.White.copy(alpha = .27f), prism + Offset(-r * .91f, r * .69f), prism + Offset(0f, r * .43f), 1.dp.toPx())\n                drawLine(Color.White.copy(alpha = .27f), prism + Offset(r * .91f, r * .69f), prism + Offset(0f, r * .43f), 1.dp.toPx())\n                val lineY = size.height * .92f\n                drawLine(s.text.copy(alpha = .15f), Offset(0f, lineY), Offset(size.width, lineY), 1.dp.toPx())\n                repeat(31) { i -> drawLine(s.text.copy(alpha = .3f), Offset(size.width * i / 30f, lineY), Offset(size.width * i / 30f, lineY - (if (i % 5 == 0) 7.dp else 3.dp).toPx()), .8.dp.toPx()) }\n            }\n            Text(\"λ \${(380 + hue * 370).toInt()} nm\", Modifier.align(Alignment.BottomStart), color = tint, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            Text(if (wide) \"DIFFUSE / 72°\" else \"FOCUS / 36°\", Modifier.align(Alignment.BottomEnd), color = s.text.copy(alpha = .6f), fontSize = 9.sp, fontFamily = FontFamily.Monospace)\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 15.dp), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f)) {\n                Text(\"CHROMATIC SHIFT\", color = s.text, fontSize = 10.sp, letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n                Text(\"拖动，寻找你的光\", Modifier.padding(top = 4.dp), color = s.text.copy(alpha = .6f), fontSize = 11.sp)\n            }\n            Box(Modifier.height(48.dp).widthIn(min = 88.dp).clip(RoundedCornerShape(24.dp)).border(1.dp, s.text.copy(alpha = .25f), RoundedCornerShape(24.dp))\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = \"切换光束扩散角度\") { wide = !wide }\n                .semantics { stateDescription = if (wide) \"扩散光束\" else \"聚焦光束\" }, contentAlignment = Alignment.Center) {\n                Text(if (wide) \"扩散 ↗\" else \"聚焦 ↗\", color = s.text, fontSize = 12.sp)\n            }\n        }\n        Slider(value = hue, onValueChange = { if (interactive) hue = it }, enabled = interactive,\n            modifier = Modifier.fillMaxWidth().height(48.dp).semantics { contentDescription = \"光谱色相\" },\n            colors = SliderDefaults.colors(thumbColor = tint, activeTrackColor = tint,\n                inactiveTrackColor = s.text.copy(alpha = .12f), disabledThumbColor = tint,\n                disabledActiveTrackColor = tint, disabledInactiveTrackColor = s.text.copy(alpha = .12f)))\n    }\n}",
        "terrain" to "@Composable\nprivate fun StyleTerrain(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var ridge by rememberSaveable { mutableStateOf(true) }\n    Column(Modifier.fillMaxWidth().background(s.bg)) {\n        Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 18.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.Top) {\n            Column {\n                Text(\"OFF THE GRID\", color = s.text, fontFamily = FontFamily.Monospace, fontSize = 9.sp, letterSpacing = 2.sp)\n                Text(\"向山而行\", Modifier.padding(top = 5.dp), color = s.text, fontSize = 28.sp, fontWeight = FontWeight.SemiBold)\n            }\n            Column(horizontalAlignment = Alignment.End) {\n                Text(\"35° / N\", color = s.text, fontFamily = FontFamily.Monospace, fontSize = 11.sp)\n                Text(\"TRAIL NOTES 018\", Modifier.padding(top = 7.dp), color = s.text.copy(alpha = .55f), fontFamily = FontFamily.Monospace, fontSize = 8.sp)\n            }\n        }\n        Box(Modifier.fillMaxWidth().height(200.dp).clip(RoundedCornerShape(0.dp))) {\n            Canvas(Modifier.fillMaxSize().semantics { contentDescription = if (ridge) \"沿山脊向东北的 8.4 公里路线\" else \"穿过溪谷向东的 5.2 公里路线\" }) {\n                drawRect(s.text.copy(alpha = .035f))\n                val peaks = listOf(Offset(size.width * .37f, size.height * .32f), Offset(size.width * .86f, size.height * .9f))\n                peaks.forEachIndexed { peakIndex, peak ->\n                    repeat(16) { contour ->\n                        val radius = (18 + contour * 13).dp.toPx()\n                        val path = Path()\n                        repeat(101) { point ->\n                            val angle = point / 100f * (PI * 2).toFloat()\n                            val wobble = 1f + .09f * sin(angle * 3f + contour * .19f) + .06f * cos(angle * 5f + peakIndex)\n                            val x = peak.x + cos(angle) * radius * wobble\n                            val y = peak.y + sin(angle) * radius * .66f * wobble\n                            if (point == 0) path.moveTo(x, y) else path.lineTo(x, y)\n                        }\n                        path.close()\n                        drawPath(path, s.text.copy(alpha = if (contour % 4 == 0) .27f else .12f), style = Stroke(if (contour % 4 == 0) 1.dp.toPx() else .65.dp.toPx()))\n                    }\n                }\n                val route = Path().apply {\n                    moveTo(size.width * .15f, size.height * .81f)\n                    if (ridge) {\n                        cubicTo(size.width * .12f, size.height * .52f, size.width * .54f, size.height * .72f, size.width * .49f, size.height * .43f)\n                        cubicTo(size.width * .43f, size.height * .14f, size.width * .8f, size.height * .5f, size.width * .84f, size.height * .14f)\n                    } else {\n                        cubicTo(size.width * .22f, size.height * .57f, size.width * .33f, size.height * .98f, size.width * .48f, size.height * .72f)\n                        cubicTo(size.width * .64f, size.height * .47f, size.width * .67f, size.height * .78f, size.width * .85f, size.height * .59f)\n                    }\n                }\n                drawPath(route, s.bg, style = Stroke(7.dp.toPx(), cap = StrokeCap.Round))\n                drawPath(route, s.extra, style = Stroke(3.dp.toPx(), cap = StrokeCap.Round, pathEffect = PathEffect.dashPathEffect(floatArrayOf(7.dp.toPx(), 4.dp.toPx()))))\n                val start = Offset(size.width * .15f, size.height * .81f)\n                val end = Offset(size.width * (if (ridge) .84f else .85f), size.height * (if (ridge) .14f else .59f))\n                drawCircle(s.bg, 6.dp.toPx(), start)\n                drawCircle(s.text, 3.dp.toPx(), start)\n                drawCircle(s.extra.copy(alpha = .16f), 14.dp.toPx(), end)\n                drawCircle(s.extra, 6.dp.toPx(), end)\n                drawCircle(s.bg, 2.dp.toPx(), end)\n                val compass = Offset(size.width - 23.dp.toPx(), size.height - 25.dp.toPx())\n                drawLine(s.text, compass - Offset(0f, 8.dp.toPx()), compass + Offset(0f, 8.dp.toPx()), 1.dp.toPx())\n                drawLine(s.text, compass - Offset(8.dp.toPx(), 0f), compass + Offset(8.dp.toPx(), 0f), 1.dp.toPx())\n                drawCircle(s.text, 2.dp.toPx(), compass)\n            }\n            Text(\"△ 1,240 m\", Modifier.align(Alignment.TopStart).padding(start = 20.dp, top = 16.dp).background(s.bg.copy(alpha = .85f)).padding(4.dp),\n                color = s.text, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            Text(\"N\", Modifier.align(Alignment.BottomEnd).padding(end = 20.dp, bottom = 39.dp), color = s.text, fontSize = 9.sp, fontFamily = FontFamily.Monospace)\n        }\n        Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 12.dp), verticalAlignment = Alignment.Bottom) {\n            Text(if (ridge) \"8.4\" else \"5.2\", color = s.text, fontSize = 43.sp, lineHeight = 46.sp, fontWeight = FontWeight.Light, letterSpacing = (-2).sp)\n            Text(\"km\", Modifier.padding(start = 5.dp, bottom = 5.dp), color = s.text.copy(alpha = .6f), fontSize = 12.sp)\n            Spacer(Modifier.weight(1f))\n            Column(horizontalAlignment = Alignment.End) {\n                Text(if (ridge) \"山脊线 / RIDGE\" else \"溪谷线 / VALLEY\", color = s.text, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)\n                Text(if (ridge) \"↑ 620 m  ·  3 h 20 min\" else \"↑ 180 m  ·  1 h 45 min\", Modifier.padding(top = 6.dp), color = s.text.copy(alpha = .6f), fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp).padding(bottom = 18.dp).border(1.dp, s.text.copy(alpha = .25f))) {\n            listOf(true to \"01 山脊探索\", false to \"02 溪谷漫步\").forEach { (isRidge, label) ->\n                Box(Modifier.weight(1f).heightIn(min = 48.dp).background(if (ridge == isRidge) s.text else Color.Transparent)\n                    .clickable(enabled = interactive, role = Role.RadioButton, onClickLabel = \"选择\${label.drop(3)}\") { ridge = isRidge }\n                    .semantics { stateDescription = if (ridge == isRidge) \"已选择\" else \"未选择\" }, contentAlignment = Alignment.Center) {\n                    Text(label, color = if (ridge == isRidge) s.bg else s.text, fontSize = 11.sp, fontFamily = FontFamily.Monospace)\n                }\n            }\n        }\n    }\n}",
        "kinetic" to "@Composable\nprivate fun StyleKinetic(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var alternate by rememberSaveable { mutableStateOf(false) }\n    Column(Modifier.fillMaxWidth().background(s.bg)) {\n        Row(Modifier.fillMaxWidth().padding(horizontal = 18.dp, vertical = 16.dp), horizontalArrangement = Arrangement.SpaceBetween) {\n            Text(\"FORM / FOLLOWS / YOU\", color = s.text, fontSize = 9.sp, letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n            Text(if (alternate) \"VOL. 02\" else \"VOL. 01\", color = s.text, fontSize = 9.sp, fontFamily = FontFamily.Monospace)\n        }\n        Box(Modifier.fillMaxWidth().height(270.dp).clip(RoundedCornerShape(0.dp))) {\n            Canvas(Modifier.fillMaxSize()) {\n                if (alternate) {\n                    drawCircle(s.text, size.width * .39f, Offset(size.width * .84f, size.height * .6f))\n                    drawCircle(s.bg, size.width * .15f, Offset(size.width * .84f, size.height * .6f))\n                    drawLine(s.text, Offset(18.dp.toPx(), size.height * .13f), Offset(size.width * .78f, size.height * .13f), 1.dp.toPx())\n                } else {\n                    val center = Offset(size.width * .78f, size.height * .42f)\n                    repeat(12) { n ->\n                        val a = n / 12f * (PI * 2).toFloat()\n                        drawLine(s.text, center + Offset(cos(a), sin(a)) * size.width * .1f,\n                            center + Offset(cos(a), sin(a)) * size.width * .2f, 8.dp.toPx())\n                    }\n                }\n            }\n            Column(Modifier.align(Alignment.TopStart).offset(x = (-5).dp, y = if (alternate) 38.dp else (-5).dp)) {\n                Text(if (alternate) \"UN—\" else \"MAKE\", color = s.text, fontSize = 91.sp, lineHeight = 84.sp,\n                    fontWeight = FontWeight.Black, letterSpacing = (-7).sp, maxLines = 1)\n                Text(if (alternate) \"RULE\" else \"SOME\", color = s.text, fontSize = 91.sp, lineHeight = 84.sp,\n                    fontWeight = FontWeight.Black, letterSpacing = (-7).sp, maxLines = 1)\n                if (!alternate) Text(\"NOISE.\", color = s.text, fontSize = 91.sp, lineHeight = 84.sp,\n                    fontWeight = FontWeight.Black, letterSpacing = (-7).sp, maxLines = 1)\n            }\n            Box(Modifier.align(Alignment.Center).offset(y = if (alternate) 61.dp else 18.dp)\n                .rotate(if (alternate) 9f else -10f).fillMaxWidth().background(s.text).padding(horizontal = 22.dp, vertical = 8.dp)) {\n                Text(if (alternate) \"灵感，从不循规蹈矩。\" else \"让 灵 感 大 声 一 点\", color = s.bg, fontSize = 16.sp,\n                    fontWeight = FontWeight.Bold, letterSpacing = 2.sp, maxLines = 1)\n            }\n            if (alternate) Text(\"BREAK THE\\nEXPECTED.\", Modifier.align(Alignment.BottomStart).padding(start = 18.dp, bottom = 12.dp),\n                color = s.text, fontSize = 13.sp, lineHeight = 15.sp, fontWeight = FontWeight.Bold)\n        }\n        Row(Modifier.fillMaxWidth().padding(horizontal = 18.dp).padding(top = 13.dp, bottom = 18.dp), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f)) {\n                Text(\"创意没有标准答案\", color = s.text, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)\n                Text(if (alternate) \"COMPOSITION 02 / DISRUPT\" else \"COMPOSITION 01 / AMPLIFY\", Modifier.padding(top = 5.dp),\n                    color = s.text.copy(alpha = .65f), fontSize = 8.sp, fontFamily = FontFamily.Monospace)\n            }\n            Box(Modifier.size(52.dp).clip(CircleShape).border(1.5.dp, s.text, CircleShape)\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = \"切换海报构图\") { alternate = !alternate }\n                .semantics { contentDescription = \"切换海报构图\"; stateDescription = if (alternate) \"构图二\" else \"构图一\" }, contentAlignment = Alignment.Center) {\n                Text(\"↗\", color = s.text, fontSize = 29.sp, fontWeight = FontWeight.Light)\n            }\n        }\n    }\n}",
        "fluidknob" to "/**\n * Adapted from Ramotion/fluid-slider-android, MIT, Copyright (c) 2017 Ramotion.\n * https://github.com/Ramotion/fluid-slider-android/blob/20ff3c9bc3e78ded1628053b6f1781ebca4e598d/fluid-slider/src/main/kotlin/com/ramotion/fluidslider/FluidSlider.kt\n * Retains drawMetaball's two-circle tangent geometry, rise-dependent spreading,\n * handle-rate calculation and two cubic joins. Replaces View/XML/Parcelable and\n * ValueAnimator with Compose Canvas, normalized state and a finite spring.\n * Adds original ink-pressure artwork, progress semantics, 48 dp step controls,\n * clamped acos inputs and a static lifted thumbnail. Credit: https://www.ramotion.com\n */\n@Composable\nprivate fun StyleFluidknob(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var value by rememberSaveable { mutableFloatStateOf(.62f) }\n    var pressed by remember { mutableStateOf(false) }\n    val rise = remember { Animatable(if (interactive) 0f else .88f) }\n    LaunchedEffect(pressed, interactive) {\n        if (interactive) rise.animateTo(if (pressed) 1f else 0f, spring(dampingRatio = .64f, stiffness = 430f))\n    }\n    val percent = (value * 100).roundToInt()\n    val largeType = LocalDensity.current.fontScale > 1.35f\n    val pressure = when { value < .34f -> \"轻盈\"; value < .7f -> \"饱满\"; else -> \"浓烈\" }\n    val accentInk = if (.2126f * s.primary.red + .7152f * s.primary.green + .0722f * s.primary.blue > .58f) Color(0xFF191E22) else Color(0xFFFFFDF6)\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(\"FLUID / INK LAB\", color = s.text.copy(alpha = .65f), fontSize = 9.sp,\n            letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n        Text(\"让手感，有点黏性\", Modifier.padding(top = 8.dp), color = s.text,\n            fontSize = 25.sp, lineHeight = 33.sp, fontWeight = FontWeight.Bold)\n        Row(Modifier.fillMaxWidth().padding(top = 16.dp), verticalAlignment = Alignment.CenterVertically) {\n            Row(Modifier.weight(if (largeType) 1.8f else 1f), verticalAlignment = Alignment.Bottom) {\n                Text(percent.toString(), color = s.primary, fontSize = if (largeType) 38.sp else 47.sp, lineHeight = 51.sp,\n                    fontFamily = FontFamily.Monospace, fontWeight = FontWeight.Light, letterSpacing = (-3).sp)\n                Text(\"%\", Modifier.padding(start = 3.dp, bottom = 5.dp), color = s.primary, fontSize = 15.sp)\n            }\n            Column(Modifier.weight(1f), horizontalAlignment = Alignment.End) {\n                Text(\"\$pressure · 墨量\", color = s.text, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)\n                Text(\"PRESSURE STUDY\", Modifier.padding(top = 5.dp), color = s.text.copy(alpha = .6f),\n                    fontSize = 8.sp, fontFamily = FontFamily.Monospace)\n            }\n        }\n        Canvas(Modifier.fillMaxWidth().height(80.dp).padding(top = 9.dp).semantics {\n            contentDescription = \"墨量 \$percent%，线条随数值变粗\"\n        }) {\n            repeat(12) { i ->\n                val x = size.width * (i + .5f) / 12\n                val amplitude = size.height * (.12f + value * .23f)\n                val stroke = 1.dp.toPx() + value * 7.dp.toPx()\n                val path = Path().apply {\n                    moveTo(x, size.height * .08f)\n                    cubicTo(x - amplitude, size.height * .34f, x + amplitude, size.height * .64f, x, size.height * .94f)\n                }\n                drawPath(path, if (i < 12 * value) s.primary else s.text.copy(alpha = .13f), style = Stroke(stroke, cap = StrokeCap.Round))\n            }\n        }\n        BoxWithConstraints(Modifier.fillMaxWidth().height(174.dp)) {\n            val density = LocalDensity.current\n            val widthPx = with(density) { maxWidth.toPx() }\n            val barHeight = with(density) { 48.dp.toPx() }\n            val barTop = with(density) { 112.dp.toPx() }\n            val radius = barHeight / 2\n            val travel = (widthPx - barHeight).coerceAtLeast(1f)\n            val bubbleX = radius + travel * value\n            val lift = rise.value.coerceIn(0f, 1.16f)\n            val bubbleY = barTop + radius - barHeight * 1.1f * lift\n            Canvas(Modifier.fillMaxSize()) {\n                drawLine(s.text.copy(alpha = .12f), Offset(radius, 52.dp.toPx()), Offset(size.width - radius, 52.dp.toPx()), 1.dp.toPx())\n                repeat(11) { i ->\n                    val x = radius + travel * i / 10\n                    drawLine(s.text.copy(alpha = .24f), Offset(x, 49.dp.toPx()), Offset(x, 55.dp.toPx()), 1.dp.toPx())\n                }\n                drawRoundRect(s.primary, Offset(0f, barTop), Size(size.width, barHeight), CornerRadius(3.dp.toPx()))\n                // A large virtual lower circle provides a nearly flat reservoir edge.\n                val lowerRadius = barHeight * 12.5f\n                val lowerCenter = Offset(bubbleX, barTop + lowerRadius)\n                clipRect(0f, 0f, size.width, size.height) {\n                    val bridge = fluidknobBridge(lowerCenter, lowerRadius, Offset(bubbleX, bubbleY), radius,\n                        barTop, barHeight * 1.1f, 2.dp.toPx())\n                    if (bridge != null) drawPath(bridge, s.primary)\n                    drawCircle(s.primary, radius, Offset(bubbleX, bubbleY))\n                }\n                drawCircle(s.bg, radius - 5.dp.toPx(), Offset(bubbleX, bubbleY))\n                drawCircle(s.extra, 3.dp.toPx(), Offset(12.dp.toPx(), barTop + radius))\n                drawCircle(accentInk.copy(alpha = .7f), 3.dp.toPx(), Offset(size.width - 12.dp.toPx(), barTop + radius))\n            }\n            Box(Modifier.offset {\n                IntOffset((bubbleX - radius).roundToInt(), (bubbleY - radius).roundToInt())\n            }.size(48.dp).clearAndSetSemantics { }, contentAlignment = Alignment.Center) {\n                Text(percent.toString(), color = s.text, fontSize = 12.sp, fontWeight = FontWeight.Bold,\n                    fontFamily = FontFamily.Monospace, maxLines = 1)\n            }\n            val touch = if (interactive) Modifier.pointerInput(widthPx) {\n                awaitEachGesture {\n                    val down = awaitFirstDown(requireUnconsumed = false)\n                    value = ((down.position.x - radius) / travel).coerceIn(0f, 1f)\n                    pressed = true\n                    try {\n                        horizontalDrag(down.id) { change ->\n                            value = ((change.position.x - radius) / travel).coerceIn(0f, 1f)\n                            change.consume()\n                        }\n                    } finally {\n                        pressed = false\n                    }\n                }\n            } else Modifier\n            Box(Modifier.align(Alignment.BottomCenter).fillMaxWidth().height(64.dp).then(touch).semantics {\n                contentDescription = \"调节墨量\"\n                stateDescription = \"\$percent%，\$pressure\"\n                progressBarRangeInfo = ProgressBarRangeInfo(value * 100, 0f..100f, 99)\n                if (interactive) setProgress { requested -> value = (requested / 100).coerceIn(0f, 1f); true }\n            })\n        }\n        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {\n            Box(Modifier.size(48.dp).border(1.dp, s.text.copy(alpha = .25f), CircleShape)\n                .clickable(enabled = interactive && value > 0f, role = Role.Button, onClickLabel = \"墨量减少百分之十\") { value = (value - .1f).coerceAtLeast(0f) }\n                .semantics { contentDescription = \"减少墨量\" }, contentAlignment = Alignment.Center) {\n                Text(\"−\", color = s.text, fontSize = 23.sp)\n            }\n            Text(\"按住轨道，让气泡浮起\", Modifier.weight(1f).padding(horizontal = 12.dp), color = s.text.copy(alpha = .6f),\n                fontSize = 10.sp, lineHeight = 16.sp)\n            Box(Modifier.size(48.dp).border(1.dp, s.text.copy(alpha = .25f), CircleShape)\n                .clickable(enabled = interactive && value < 1f, role = Role.Button, onClickLabel = \"墨量增加百分之十\") { value = (value + .1f).coerceAtMost(1f) }\n                .semantics { contentDescription = \"增加墨量\" }, contentAlignment = Alignment.Center) {\n                Text(\"+\", color = s.text, fontSize = 23.sp)\n            }\n        }\n    }\n}\n\nprivate fun fluidknobBridge(c1: Offset, r1: Float, c2: Offset, r2: Float, top: Float, riseDistance: Float, edge: Float): Path? {\n    val d = (c2 - c1).getDistance()\n    if (r1 <= 0f || r2 <= 0f || d <= abs(r1 - r2) || d > r1 + r2 + riseDistance * 3) return null\n    fun safeAcos(v: Float) = acos(v.coerceIn(-1f, 1f))\n    fun vector(angle: Float, radius: Float) = Offset(cos(angle) * radius, sin(angle) * radius)\n    val lift = ((top - (c2.y - r2)) / riseDistance).coerceIn(0f, 1f)\n    val u1 = if (d < r1 + r2) safeAcos((r1 * r1 + d * d - r2 * r2) / (2 * r1 * d)) else 0f\n    val u2 = if (d < r1 + r2) safeAcos((r2 * r2 + d * d - r1 * r1) / (2 * r2 * d)) else 0f\n    val bottomSpread = .25f - .15f * lift\n    val topSpread = .4f\n    val angle1 = atan2(c2.y - c1.y, c2.x - c1.x)\n    val angle2 = safeAcos((r1 - r2) / d)\n    val a1 = angle1 + u1 + (angle2 - u1) * bottomSpread\n    val b1 = angle1 - u1 - (angle2 - u1) * bottomSpread\n    val a2 = angle1 + PI.toFloat() - u2 - (PI.toFloat() - u2 - angle2) * topSpread\n    val b2 = angle1 - PI.toFloat() + u2 + (PI.toFloat() - u2 - angle2) * topSpread\n    val p1a = c1 + vector(a1, r1)\n    val p1b = c1 + vector(b1, r1)\n    val p2a = c2 + vector(a2, r2)\n    val p2b = c2 + vector(b2, r2)\n    val handle = min(maxOf(topSpread, bottomSpread) * 2.4f, (p1a - p2a).getDistance() / (r1 + r2)) * min(1f, d * 2 / (r1 + r2))\n    val halfPi = PI.toFloat() / 2\n    val h1 = vector(a1 - halfPi, r1 * handle)\n    val h2 = vector(a2 + halfPi, r2 * handle)\n    val h3 = vector(b2 - halfPi, r2 * handle)\n    val h4 = vector(b1 + halfPi, r1 * handle)\n    val shift = abs(top - p1a.y) * lift - 1f\n    val left = p1a - Offset(0f, shift)\n    val right = p1b - Offset(0f, shift)\n    return Path().apply {\n        moveTo(left.x, left.y + edge); lineTo(left.x, left.y)\n        cubicTo(left.x + h1.x, left.y + h1.y, p2a.x + h2.x, p2a.y + h2.y, p2a.x, p2a.y)\n        lineTo(c2.x, c2.y); lineTo(p2b.x, p2b.y)\n        cubicTo(p2b.x + h3.x, p2b.y + h3.y, right.x + h4.x, right.y + h4.y, right.x, right.y)\n        lineTo(right.x, right.y + edge); close()\n    }\n}",
        "radialtool" to "/**\n * Adapted from skydoves/compose-animations, Apache License 2.0.\n * Designed and developed by 2026 skydoves (Jaewoong Eum).\n * https://github.com/skydoves/compose-animations/blob/eb51389891c303a0ad79c73525bd97acfdf96547/app/src/main/kotlin/com/skydoves/hotreloadanimations/animations/AnimationExample14.kt\n * Retains per-satellite Animatable springs, polar placement, staggered opening\n * and reversed closing. Replaces the demo with four original selectable Canvas\n * stamps, bounded responsive geometry, accessibility semantics, a next-stamp\n * button and a non-animated open thumbnail. No HotSwan or other library is used.\n */\n@Composable\nprivate fun StyleRadialtool(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var selected by rememberSaveable { mutableIntStateOf(0) }\n    var open by rememberSaveable { mutableStateOf(true) }\n    val names = listOf(\"光芒\", \"涟漪\", \"交织\", \"回声\")\n    val hints = listOf(\"RADIATE / 12 RAYS\", \"RIPPLE / CONCENTRIC\", \"WEAVE / INTERSECTION\", \"ECHO / WAVEFORMS\")\n    val palette = listOf(s.primary, s.extra, Color(0xFFEBAE79), Color(0xFFA59ABD))\n    val progresses = remember { List(4) { Animatable(if (open || !interactive) 1f else 0f) } }\n    LaunchedEffect(open, interactive) {\n        if (!interactive) return@LaunchedEffect\n        progresses.forEachIndexed { index, progress ->\n            val target = if (open) 1f else 0f\n            if (progress.value != target) launch {\n                delay((if (open) index else 3 - index) * 50L)\n                progress.animateTo(target, spring(dampingRatio = .58f, stiffness = 460f))\n            }\n        }\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(\"FIELD / STAMP COMPASS\", color = s.text.copy(alpha = .65f), fontSize = 9.sp,\n            letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n        Text(\"工具，也可以有轨道\", Modifier.padding(top = 8.dp), color = s.text, fontSize = 25.sp,\n            lineHeight = 33.sp, fontWeight = FontWeight.Bold)\n        BoxWithConstraints(Modifier.fillMaxWidth().height(280.dp)) {\n            val density = LocalDensity.current\n            val radius = with(density) { min(maxWidth.toPx(), 280.dp.toPx()) * .32f }\n            val ink = s.text\n            Canvas(Modifier.fillMaxSize()) {\n                drawCircle(s.panel, radius * .72f)\n                drawCircle(ink.copy(alpha = .16f), radius, style = Stroke(1.dp.toPx()))\n                drawCircle(ink.copy(alpha = .1f), radius * 1.24f, style = Stroke(.7.dp.toPx()))\n                repeat(48) { i ->\n                    val angle = i * PI.toFloat() / 24\n                    val direction = Offset(cos(angle), sin(angle))\n                    drawLine(ink.copy(alpha = .35f), center + direction * radius * 1.2f,\n                        center + direction * radius * (if (i % 4 == 0) 1.28f else 1.23f), .8.dp.toPx())\n                }\n                progresses.forEachIndexed { index, progress ->\n                    val angle = (-90 + index * 90) * PI.toFloat() / 180\n                    val v = if (interactive) progress.value else 1f\n                    val direction = Offset(cos(angle), sin(angle))\n                    drawLine(ink.copy(alpha = .15f * v.coerceIn(0f, 1f)), center + direction * 45.dp.toPx(),\n                        center + direction * radius * v, 1.dp.toPx())\n                }\n            }\n            progresses.forEachIndexed { index, progress ->\n                val angle = (-90 + index * 90) * PI.toFloat() / 180\n                val inkOnColor = if (.2126f * palette[index].red + .7152f * palette[index].green + .0722f * palette[index].blue > .58f) Color(0xFF222622) else Color(0xFFFFFDF7)\n                val select = if (open && interactive) Modifier.selectable(selected == index, role = Role.RadioButton) {\n                    selected = index\n                    open = false\n                }.semantics { contentDescription = \"选择\${names[index]}印章\" } else Modifier.clearAndSetSemantics { }\n                Box(Modifier.align(Alignment.Center).size(52.dp).graphicsLayer {\n                    val v = if (interactive) progress.value else 1f\n                    translationX = radius * cos(angle) * v\n                    translationY = radius * sin(angle) * v\n                    scaleX = .4f + .6f * v\n                    scaleY = scaleX\n                    alpha = v.coerceIn(0f, 1f)\n                }.clip(CircleShape).background(palette[index])\n                    .then(if (index == selected) Modifier.border(2.dp, s.text, CircleShape) else Modifier)\n                    .then(select), contentAlignment = Alignment.Center) {\n                    Canvas(Modifier.size(27.dp)) { radialtoolStamp(index, center, size.minDimension * .4f, inkOnColor) }\n                }\n            }\n            Box(Modifier.align(Alignment.Center).size(88.dp).clip(CircleShape).background(s.text)\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = if (open) \"收起工具盘\" else \"展开工具盘\") { open = !open }\n                .semantics { contentDescription = if (open) \"收起工具盘\" else \"展开工具盘\"; stateDescription = \"当前\${names[selected]}印章\" }, contentAlignment = Alignment.Center) {\n                Canvas(Modifier.size(57.dp)) { radialtoolStamp(selected, center, size.minDimension * .42f, s.bg) }\n            }\n        }\n        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f).padding(end = 8.dp)) {\n                Text(\"\${names[selected]} / 0\${selected + 1}\", color = s.text, fontSize = 18.sp, fontWeight = FontWeight.Bold)\n                Text(hints[selected], Modifier.padding(top = 5.dp), color = s.text.copy(alpha = .6f),\n                    fontSize = 8.sp, fontFamily = FontFamily.Monospace, maxLines = 2, overflow = TextOverflow.Ellipsis)\n            }\n            Button(onClick = { selected = (selected + 1) % names.size }, enabled = interactive,\n                modifier = Modifier.heightIn(min = 48.dp).semantics { contentDescription = \"选择下一枚印章\" },\n                shape = RoundedCornerShape(4.dp), colors = ButtonDefaults.buttonColors(containerColor = s.text,\n                    contentColor = s.bg, disabledContainerColor = s.text, disabledContentColor = s.bg)) {\n                Text(\"换一枚 ↗\", fontSize = 11.sp)\n            }\n        }\n        Text(if (open) \"选择一个方向，把形状留在中心\" else \"轻触中心，再次展开工具盘\", Modifier.padding(top = 12.dp),\n            color = s.text.copy(alpha = .6f), fontSize = 10.sp, lineHeight = 16.sp)\n    }\n}\n\nprivate fun DrawScope.radialtoolStamp(index: Int, center: Offset, radius: Float, color: Color) {\n    when (index) {\n        0 -> repeat(12) { i ->\n            val angle = i * PI.toFloat() / 6\n            val d = Offset(cos(angle), sin(angle))\n            drawLine(color, center + d * radius * .4f, center + d * radius, radius * .14f, StrokeCap.Round)\n        }\n        1 -> repeat(4) { i -> drawCircle(color, radius * (.25f + i * .25f), center, style = Stroke(radius * .08f)) }\n        2 -> {\n            repeat(4) { i ->\n                rotate(45f + i * 45, center) {\n                    drawOval(color, center - Offset(radius, radius * .32f), Size(radius * 2, radius * .64f), style = Stroke(radius * .09f))\n                }\n            }\n        }\n        else -> repeat(4) { i ->\n            val y = center.y - radius * .75f + i * radius * .5f\n            val path = Path().apply {\n                moveTo(center.x - radius, y)\n                cubicTo(center.x - radius * .25f, y - radius * .6f, center.x + radius * .25f, y + radius * .6f, center.x + radius, y)\n            }\n            drawPath(path, color, style = Stroke(radius * .1f, cap = StrokeCap.Round))\n        }\n    }\n}",
        "fielddots" to "// Adapted from drawcall/Proton, commit b4fdef5e5416d70a788978bec0fb4a1be26514b4:\n// src/behaviour/Attraction.js, src/behaviour/Repulsion.js, src/math/Integration.js.\n// MIT License, Copyright (c) Proton authors. See exported full license.\n// Changes: only radius-squared falloff, force reversal and damped Euler integration are\n// ported. Added home springs, fixed simulation steps, speed bounds, 99 deterministic dots,\n// finite velocity trails and native accessible controls. No JS engine, images or renderer.\n@Composable\nprivate fun StyleFielddots(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var fieldX by rememberSaveable { mutableFloatStateOf(.62f) }\n    var fieldY by rememberSaveable { mutableFloatStateOf(.44f) }\n    var mode by rememberSaveable { mutableIntStateOf(1) }\n    var strength by rememberSaveable { mutableFloatStateOf(.65f) }\n    var running by rememberSaveable { mutableStateOf(true) }\n    val dots = remember { FielddotsInitial() }\n    var frame by remember { mutableIntStateOf(0) }\n    val fontScale = LocalDensity.current.fontScale\n\n    // No frame callback is started by gallery thumbnails. Cancellation also stops the\n    // simulation immediately on pause or when the detail leaves composition.\n    LaunchedEffect(interactive, running) {\n        if (!interactive || !running) return@LaunchedEffect\n        var previousTime = 0L\n        var accumulator = 0f\n        val step = 1f / 60f\n        while (isActive) {\n            withFrameNanos { now ->\n                if (previousTime != 0L) {\n                    // Discard long background gaps instead of fast-forwarding the physics.\n                    accumulator += ((now - previousTime) / 1_000_000_000f).coerceIn(0f, .05f)\n                    while (accumulator >= step) {\n                        FielddotsStep(dots, fieldX, fieldY, strength, mode, step)\n                        accumulator -= step\n                    }\n                    frame = (frame + 1) % 1_000_000\n                }\n                previousTime = now\n            }\n        }\n    }\n\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Text(\"FIELD NOTES / 003\", color = s.extra, fontFamily = FontFamily.Monospace,\n            fontSize = 10.sp, letterSpacing = 1.3.sp)\n        Text(p.headline, color = s.text, fontSize = 30.sp, lineHeight = 38.sp, fontWeight = FontWeight.Bold)\n        Text(p.caption, color = s.text.copy(alpha = .67f), fontSize = 12.sp, lineHeight = 19.sp)\n\n        Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(20.dp)).background(s.panel)\n            .border(1.dp, s.text.copy(alpha = .13f), RoundedCornerShape(20.dp))) {\n            Text(if (mode == 0) \"＋  聚拢 / ATTRACT\" else if (mode == 1) \"−  推开 / REPEL\" else \"○  归位 / REST\",\n                Modifier.padding(start = 16.dp, end = 16.dp, top = 16.dp), color = s.primary,\n                fontSize = 11.sp, lineHeight = 16.sp, fontFamily = FontFamily.Monospace)\n            Canvas(Modifier.fillMaxWidth().height(290.dp)\n                .semantics {\n                    contentDescription = \"可拖动的磁场点阵。下方可选择吸引、排斥、归位与磁场位置\"\n                    stateDescription = if (!interactive) \"静态排斥构图\" else\n                        \"\${if (running) \"运动中\" else \"已暂停\"}，磁场横向 \${(fieldX * 100).roundToInt()}%，纵向 \${(fieldY * 100).roundToInt()}%\"\n                }\n                .then(if (interactive) Modifier.pointerInput(Unit) {\n                    detectDragGestures(\n                        onDragStart = { at ->\n                            fieldX = (at.x / size.width).coerceIn(.12f, .88f)\n                            fieldY = (at.y / size.height).coerceIn(.12f, .88f)\n                            running = true\n                        },\n                        onDrag = { change, _ ->\n                            change.consume()\n                            fieldX = (change.position.x / size.width).coerceIn(.12f, .88f)\n                            fieldY = (change.position.y / size.height).coerceIn(.12f, .88f)\n                        }\n                    )\n                } else Modifier)) {\n                @Suppress(\"UNUSED_VARIABLE\") val drawnFrame = frame\n                val unit = min(size.width, size.height)\n                val center = Offset(fieldX * size.width, fieldY * size.height)\n                val influence = unit * .30f\n                // A sparse registration grid makes displacement readable without moving text.\n                for (row in 0..4) for (col in 0..4) {\n                    val point = Offset(size.width * (.075f + col * .2125f), size.height * (.075f + row * .2125f))\n                    drawLine(s.text.copy(alpha = .075f), point - Offset(3.dp.toPx(), 0f), point + Offset(3.dp.toPx(), 0f), 1.dp.toPx())\n                    drawLine(s.text.copy(alpha = .075f), point - Offset(0f, 3.dp.toPx()), point + Offset(0f, 3.dp.toPx()), 1.dp.toPx())\n                }\n                if (mode != 2) {\n                    drawCircle(s.primary.copy(alpha = .035f), influence, center)\n                    drawCircle(s.primary.copy(alpha = .22f), influence, center,\n                        style = Stroke(1.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(3.dp.toPx(), 7.dp.toPx()))))\n                }\n                dots.forEachIndexed { index, dot ->\n                    val at = Offset(dot.x * size.width, dot.y * size.height)\n                    val displacement = sqrt((dot.x - dot.homeX) * (dot.x - dot.homeX) + (dot.y - dot.homeY) * (dot.y - dot.homeY))\n                    val emphasis = (displacement * 6f).coerceIn(0f, 1f)\n                    val color = if (index % 4 == 0) s.extra else s.primary\n                    val tail = Offset((dot.vx * size.width * .085f).coerceIn(-22.dp.toPx(), 22.dp.toPx()),\n                        (dot.vy * size.height * .085f).coerceIn(-22.dp.toPx(), 22.dp.toPx()))\n                    drawLine(color.copy(alpha = .30f), at - tail, at, 1.dp.toPx(), StrokeCap.Round)\n                    drawCircle(color.copy(alpha = .06f + emphasis * .12f), (4.5f + emphasis * 2.5f).dp.toPx(), at)\n                    drawCircle(color.copy(alpha = .45f + emphasis * .55f), (1.6f + emphasis * .8f).dp.toPx(), at)\n                }\n                if (mode != 2) {\n                    drawCircle(s.panel, 13.dp.toPx(), center)\n                    drawCircle(s.primary, 10.dp.toPx(), center, style = Stroke(1.3.dp.toPx()))\n                    drawLine(s.primary, center - Offset(4.dp.toPx(), 0f), center + Offset(4.dp.toPx(), 0f), 1.5.dp.toPx())\n                    if (mode == 0) drawLine(s.primary, center - Offset(0f, 4.dp.toPx()), center + Offset(0f, 4.dp.toPx()), 1.5.dp.toPx())\n                }\n            }\n            Text(if (interactive) \"拖动亮点，改变这一小片秩序。\" else \"一小片秩序，正在被轻轻推开。\",\n                Modifier.padding(horizontal = 16.dp).padding(bottom = 16.dp), color = s.text.copy(alpha = .55f),\n                fontSize = 10.sp, lineHeight = 16.sp)\n        }\n\n        if (interactive) {\n            FielddotsControls(s, listOf(\"吸引\", \"排斥\", \"归位\"), mode, fontScale > 1.6f) { next ->\n                mode = next\n                running = true\n            }\n            Text(\"磁场位置\", color = s.text.copy(alpha = .7f), fontSize = 11.sp)\n            FielddotsControls(s, listOf(\"左上\", \"中央\", \"右下\"), -1, fontScale > 1.6f) { preset ->\n                fieldX = listOf(.28f, .5f, .72f)[preset]\n                fieldY = listOf(.28f, .5f, .72f)[preset]\n                running = true\n            }\n            HorizontalDivider(color = s.text.copy(alpha = .12f))\n            Text(\"力度  \${(strength * 100).roundToInt()}%\", color = s.text, fontSize = 12.sp)\n            Slider(value = strength, onValueChange = { strength = it; running = true }, valueRange = .15f..1f,\n                modifier = Modifier.fillMaxWidth().semantics { contentDescription = \"磁场力度\" },\n                colors = SliderDefaults.colors(thumbColor = s.primary, activeTrackColor = s.primary,\n                    inactiveTrackColor = s.text.copy(alpha = .16f)))\n            TextButton(onClick = { running = !running }, modifier = Modifier.fillMaxWidth().heightIn(min = 48.dp),\n                colors = ButtonDefaults.textButtonColors(contentColor = s.primary)) {\n                Text(if (running) \"暂停运动\" else \"继续运动\", fontSize = 13.sp, textAlign = TextAlign.Center)\n            }\n        } else {\n            Text(\"触碰 · 偏移 · 回弹\", color = s.text.copy(alpha = .66f), fontSize = 11.sp, letterSpacing = 1.sp)\n        }\n    }\n}\n\n@Composable\nprivate fun FielddotsControls(s: CreativeStyleSpec, labels: List<String>, selected: Int, stacked: Boolean,\n    onSelect: (Int) -> Unit) {\n    val content: @Composable (Int, Modifier) -> Unit = { index, modifier ->\n        TextButton(onClick = { onSelect(index) }, modifier = modifier.heightIn(min = 48.dp)\n            .border(1.dp, if (selected == index) s.primary else s.text.copy(alpha = .15f), RoundedCornerShape(12.dp))\n            .semantics { if (selected == index) stateDescription = \"已选中\" },\n            colors = ButtonDefaults.textButtonColors(contentColor = if (selected == index) s.primary else s.text)) {\n            Text(labels[index], fontSize = 12.sp, textAlign = TextAlign.Center)\n        }\n    }\n    if (stacked) Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(6.dp)) {\n        labels.indices.forEach { content(it, Modifier.fillMaxWidth()) }\n    } else Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {\n        labels.indices.forEach { content(it, Modifier.weight(1f)) }\n    }\n}\n\nprivate data class FielddotsParticle(val homeX: Float, val homeY: Float,\n    var x: Float = homeX, var y: Float = homeY, var vx: Float = 0f, var vy: Float = 0f)\n\nprivate fun FielddotsInitial(): List<FielddotsParticle> {\n    // Fixed seed-free layout makes exports and static thumbnails deterministic.\n    val dots = List(99) { index -> FielddotsParticle(.075f + (index % 11) * .085f, .075f + (index / 11) * .10625f) }\n    repeat(70) { FielddotsStep(dots, .62f, .44f, .65f, 1, 1f / 60f) }\n    return dots\n}\n\nprivate fun FielddotsStep(dots: List<FielddotsParticle>, fieldX: Float, fieldY: Float,\n    strength: Float, mode: Int, dt: Float) {\n    val radiusSquared = .30f * .30f\n    dots.forEach { dot ->\n        // Home springs are a native adaptation; Proton supplies the radial force below.\n        var ax = (dot.homeX - dot.x) * 11f\n        var ay = (dot.homeY - dot.y) * 11f\n        val dx = fieldX - dot.x\n        val dy = fieldY - dot.y\n        val distanceSquared = dx * dx + dy * dy\n        if (mode != 2 && distanceSquared > .000004f && distanceSquared < radiusSquared) {\n            val force = (1f - distanceSquared / radiusSquared) * strength * 4f * (if (mode == 0) 1f else -1f)\n            val inverseDistance = 1f / sqrt(distanceSquared)\n            ax += dx * inverseDistance * force\n            ay += dy * inverseDistance * force\n        }\n        // Proton Euler order: position uses the old velocity, then velocity is damped.\n        val previousVx = dot.vx\n        val previousVy = dot.vy\n        dot.vx = ((dot.vx + ax * dt) * .91f).coerceIn(-1.2f, 1.2f)\n        dot.vy = ((dot.vy + ay * dt) * .91f).coerceIn(-1.2f, 1.2f)\n        dot.x = (dot.x + previousVx * dt).coerceIn(.025f, .975f)\n        dot.y = (dot.y + previousVy * dt).coerceIn(.025f, .975f)\n        if ((dot.x <= .025f && dot.vx < 0) || (dot.x >= .975f && dot.vx > 0)) dot.vx = 0f\n        if ((dot.y <= .025f && dot.vy < 0) || (dot.y >= .975f && dot.vy > 0)) dot.vy = 0f\n    }\n}",
        "morphstamp" to "// Adapted from veltman/flubber, 0cadadf3eb15cd5b2ec7c45c70601ff88b76a6c3:\n// src/add.js (addPoints), src/rotate.js, src/math.js (interpolatePoint).\n// MIT License, Copyright (c) 2017 Noah Veltman. See exported full license.\n// Changes: native Offset/Path instead of SVG/JS; three original clockwise silhouettes,\n// 96-point bounded rings, cached point matching, finite gesture-driven transitions and\n// slider/button alternatives. No SVG parser, D3, upstream art or splitting/merging engine.\n@Composable\nprivate fun StyleMorphstamp(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var position by rememberSaveable { mutableFloatStateOf(.42f) }\n    var scrubbing by remember { mutableStateOf(false) }\n    val progress by animateFloatAsState(\n        targetValue = if (interactive) position else .42f,\n        animationSpec = if (interactive && !scrubbing) tween(650) else snap(),\n        label = \"morphstamp-progress\"\n    )\n    val rings = remember { MorphstampRings() }\n    val names = listOf(\"芒星\", \"十字\", \"徽盾\")\n    val segment = floor(progress).toInt().coerceIn(0, 1)\n    val amount = (progress - segment).coerceIn(0f, 1f)\n    val contour = remember(progress, rings) {\n        rings[segment].mapIndexed { index, point -> MorphstampPointAlong(point, rings[segment + 1][index], amount) }\n    }\n    val largeFont = LocalDensity.current.fontScale > 1.5f\n\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {\n        Text(\"FORM PRESS / 03\", fontFamily = FontFamily.Monospace, fontSize = 10.sp,\n            letterSpacing = 1.2.sp, color = s.text.copy(alpha = .66f))\n        Text(p.headline, color = s.text, fontSize = 31.sp, lineHeight = 39.sp, fontWeight = FontWeight.Black)\n        Text(p.caption, color = s.text.copy(alpha = .65f), fontSize = 12.sp, lineHeight = 19.sp)\n        HorizontalDivider(color = s.text.copy(alpha = .25f))\n\n        Canvas(Modifier.fillMaxWidth().height(294.dp)\n            .semantics {\n                contentDescription = \"可变形的印章轮廓：芒星、十字与徽盾。下方按钮或滑块也可控制形状\"\n                stateDescription = \"\${names[segment]}到\${names[segment + 1]}，\${(amount * 100).roundToInt()}%\"\n            }\n            .then(if (interactive) Modifier.pointerInput(Unit) {\n                detectHorizontalDragGestures(\n                    onDragStart = { position = progress; scrubbing = true },\n                    onDragEnd = { scrubbing = false },\n                    onDragCancel = { scrubbing = false }\n                ) { change, delta ->\n                    change.consume()\n                    position = (position + delta / size.width.coerceAtLeast(1) * 2f).coerceIn(0f, 2f)\n                }\n            } else Modifier)) {\n            val extent = size.minDimension * .345f\n            val middle = Offset(size.width * .5f, size.height * .5f)\n            // Print-registration marks belong to the original gallery artwork.\n            val mark = 7.dp.toPx()\n            listOf(Offset(7.dp.toPx(), 16.dp.toPx()), Offset(size.width - 7.dp.toPx(), 16.dp.toPx()),\n                Offset(7.dp.toPx(), size.height - 16.dp.toPx()), Offset(size.width - 7.dp.toPx(), size.height - 16.dp.toPx())).forEach { point ->\n                drawLine(s.text.copy(alpha = .32f), point - Offset(mark, 0f), point + Offset(mark, 0f), 1.dp.toPx())\n                drawLine(s.text.copy(alpha = .32f), point - Offset(0f, mark), point + Offset(0f, mark), 1.dp.toPx())\n            }\n            // The two offset impressions change with the same matched contour.\n            val underprint = MorphstampPath(contour, middle + Offset(12.dp.toPx(), 16.dp.toPx()), extent)\n            rotate(7f, middle) { drawPath(underprint, s.extra) }\n            val wireprint = MorphstampPath(contour, middle - Offset(10.dp.toPx(), 13.dp.toPx()), extent)\n            rotate(-8f, middle) { drawPath(wireprint, s.text.copy(alpha = .38f), style = Stroke(1.dp.toPx())) }\n            val shape = MorphstampPath(contour, middle, extent)\n            drawPath(shape, s.primary)\n            // A small engraved cross stays inside every silhouette and reinforces the print theme.\n            drawLine(s.bg.copy(alpha = .85f), middle - Offset(10.dp.toPx(), 0f), middle + Offset(10.dp.toPx(), 0f), 1.dp.toPx())\n            drawLine(s.bg.copy(alpha = .85f), middle - Offset(0f, 10.dp.toPx()), middle + Offset(0f, 10.dp.toPx()), 1.dp.toPx())\n        }\n\n        Text(\"\${names[segment]}  →  \${names[segment + 1]}  /  \${(amount * 100).roundToInt()}%\",\n            color = s.text, fontFamily = FontFamily.Monospace, fontSize = 12.sp, lineHeight = 19.sp)\n        Text(if (interactive) \"左右拖动印章，停在你喜欢的轮廓。\" else \"轮廓之间，还有无数种可能。\",\n            color = s.text.copy(alpha = .62f), fontSize = 11.sp, lineHeight = 18.sp)\n\n        if (interactive) {\n            Slider(value = position, onValueChange = { scrubbing = true; position = it },\n                onValueChangeFinished = { scrubbing = false }, valueRange = 0f..2f,\n                modifier = Modifier.fillMaxWidth().semantics { contentDescription = \"形态变化进度，依次经过芒星、十字、徽盾\" },\n                colors = SliderDefaults.colors(thumbColor = s.primary, activeTrackColor = s.primary,\n                    inactiveTrackColor = s.text.copy(alpha = .13f)))\n            if (largeFont) {\n                Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(7.dp)) {\n                    names.forEachIndexed { index, name ->\n                        MorphstampChoice(s, name, abs(position - index) < .03f, Modifier.fillMaxWidth()) {\n                            scrubbing = false; position = index.toFloat()\n                        }\n                    }\n                }\n            } else {\n                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(7.dp)) {\n                    names.forEachIndexed { index, name ->\n                        MorphstampChoice(s, name, abs(position - index) < .03f, Modifier.weight(1f)) {\n                            scrubbing = false; position = index.toFloat()\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n\n@Composable\nprivate fun MorphstampChoice(s: CreativeStyleSpec, name: String, selected: Boolean, modifier: Modifier,\n    onClick: () -> Unit) {\n    TextButton(onClick = onClick, modifier = modifier.heightIn(min = 48.dp)\n        .border(1.dp, if (selected) s.primary else s.text.copy(alpha = .18f), RoundedCornerShape(12.dp))\n        .semantics { stateDescription = if (selected) \"已选中\" else \"切换为\$name\" },\n        colors = ButtonDefaults.textButtonColors(contentColor = if (selected) s.primary else s.text)) {\n        Text(name, fontSize = 12.sp, textAlign = TextAlign.Center)\n    }\n}\n\nprivate fun MorphstampRings(): List<List<Offset>> {\n    val star = List(16) { index ->\n        val angle = (-PI / 2 + PI * 2 * index / 16).toFloat()\n        val radius = if (index % 2 == 0) .98f else .56f\n        Offset(cos(angle) * radius, sin(angle) * radius)\n    }\n    val cross = listOf(Offset(-.28f, -.91f), Offset(.28f, -.91f), Offset(.28f, -.28f), Offset(.91f, -.28f),\n        Offset(.91f, .28f), Offset(.28f, .28f), Offset(.28f, .91f), Offset(-.28f, .91f),\n        Offset(-.28f, .28f), Offset(-.91f, .28f), Offset(-.91f, -.28f), Offset(-.28f, -.28f))\n    val shield = listOf(Offset(0f, -.92f), Offset(.80f, -.58f), Offset(.72f, .26f), Offset(.43f, .70f),\n        Offset(0f, .98f), Offset(-.43f, .70f), Offset(-.72f, .26f), Offset(-.80f, -.58f))\n    val first = MorphstampAddPoints(star, 96)\n    val second = MorphstampAlign(MorphstampAddPoints(cross, 96), first)\n    val third = MorphstampAlign(MorphstampAddPoints(shield, 96), second)\n    return listOf(first, second, third)\n}\n\nprivate fun MorphstampPointAlong(a: Offset, b: Offset, progress: Float): Offset =\n    Offset(a.x + (b.x - a.x) * progress, a.y + (b.y - a.y) * progress)\n\nprivate fun MorphstampDistance(a: Offset, b: Offset): Float {\n    val dx = a.x - b.x\n    val dy = a.y - b.y\n    return sqrt(dx * dx + dy * dy)\n}\n\nprivate fun MorphstampAddPoints(input: List<Offset>, desired: Int): List<Offset> {\n    val ring = input.toMutableList()\n    val added = desired - ring.size\n    if (added <= 0 || ring.isEmpty()) return ring\n    var perimeter = 0f\n    ring.indices.forEach { perimeter += MorphstampDistance(ring[it], ring[(it + 1) % ring.size]) }\n    if (perimeter <= .000001f) return List(desired) { ring.first() }\n    // Flubber inserts extra points half a step into the perimeter, retaining all corners.\n    val step = perimeter / added\n    var cursor = 0f\n    var insertAt = step / 2f\n    var index = 0\n    while (ring.size < desired) {\n        val a = ring[index]\n        val b = ring[(index + 1) % ring.size]\n        val segment = MorphstampDistance(a, b)\n        if (insertAt <= cursor + segment) {\n            ring.add(index + 1, if (segment > .000001f) MorphstampPointAlong(a, b, ((insertAt - cursor) / segment).coerceIn(0f, 1f)) else a)\n            insertAt += step\n        } else {\n            cursor += segment\n            index = (index + 1) % ring.size\n        }\n    }\n    return ring\n}\n\nprivate fun MorphstampAlign(ring: List<Offset>, reference: List<Offset>): List<Offset> {\n    // Flubber's rotation matcher minimizes squared point travel over every cyclic start.\n    var bestOffset = 0\n    var bestScore = Float.POSITIVE_INFINITY\n    ring.indices.forEach { offset ->\n        var score = 0f\n        reference.indices.forEach { index ->\n            val difference = ring[(offset + index) % ring.size] - reference[index]\n            score += difference.x * difference.x + difference.y * difference.y\n        }\n        if (score < bestScore) { bestScore = score; bestOffset = offset }\n    }\n    return List(ring.size) { ring[(bestOffset + it) % ring.size] }\n}\n\nprivate fun MorphstampPath(ring: List<Offset>, center: Offset, scale: Float): Path = Path().apply {\n    ring.forEachIndexed { index, point ->\n        val x = center.x + point.x * scale\n        val y = center.y + point.y * scale\n        if (index == 0) moveTo(x, y) else lineTo(x, y)\n    }\n    close()\n}",
        "foiltilt" to "// Adapted from micku7zu/vanilla-tilt.js, MIT, Copyright (c) 2017 Șandor Sergiu.\n// https://github.com/micku7zu/vanilla-tilt.js/blob/48f4ee931d4d91dcdd2f91803db67a9f3a16587e/src/vanilla-tilt.js\n// Upstream credits the original Tilt.js by Gijs Rogé.\n// Retained: clamped pointer normalization, paired tilt angles, atan2 glare direction\n// and vertical-position glare strength from getValues/update. Changes: native touch\n// replaces browser events, Compose springs replace CSS transitions, procedural foil\n// and depth layers replace DOM content. No sensors, images, fonts or JS engine used.\n@Composable\nprivate fun StyleFoiltilt(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var touchX by rememberSaveable { mutableFloatStateOf(.68f) }\n    var touchY by rememberSaveable { mutableFloatStateOf(.38f) }\n    val x by animateFloatAsState(if (interactive) touchX else .68f,\n        spring(dampingRatio = .82f, stiffness = 340f), label = \"foil-x\")\n    val y by animateFloatAsState(if (interactive) touchY else .38f,\n        spring(dampingRatio = .82f, stiffness = 340f), label = \"foil-y\")\n    val projection = FoiltiltAngles(x, y)\n    val fontScale = LocalDensity.current.fontScale\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Text(p.caption, color = s.text.copy(alpha = .65f), fontFamily = FontFamily.Monospace,\n            fontSize = 10.sp, letterSpacing = 1.sp)\n        Text(p.headline, color = s.text, fontSize = 28.sp, lineHeight = 36.sp, fontWeight = FontWeight.Bold)\n        BoxWithConstraints(Modifier.fillMaxWidth()) {\n            val cardHeight = maxWidth * (1.38f * fontScale.coerceAtLeast(1f))\n            val gesture = if (interactive) Modifier.pointerInput(Unit) {\n                fun locate(point: Offset) {\n                    touchX = (point.x / size.width.coerceAtLeast(1)).coerceIn(0f, 1f)\n                    touchY = (point.y / size.height.coerceAtLeast(1)).coerceIn(0f, 1f)\n                }\n                detectDragGestures(onDragStart = ::locate,\n                    onDragEnd = { touchX = .5f; touchY = .5f },\n                    onDragCancel = { touchX = .5f; touchY = .5f }) { change, _ ->\n                    change.consume()\n                    locate(change.position)\n                }\n            } else Modifier\n            // Capture against stationary bounds so rotation never feeds back into pointer coordinates.\n            Box(Modifier.fillMaxWidth().height(cardHeight + 38.dp).then(gesture)\n                .semantics {\n                    contentDescription = \"可倾斜的全息通行证，拖动观察图案视差与反光\"\n                    stateDescription = \"横向倾斜 \${projection.first.toInt()} 度，纵向倾斜 \${projection.second.toInt()} 度\"\n                }.padding(horizontal = 14.dp, vertical = 19.dp)) {\n                Box(Modifier.fillMaxSize().graphicsLayer {\n                    rotationY = projection.first\n                    rotationX = projection.second\n                    cameraDistance = 850.dp.toPx()\n                    shadowElevation = 16.dp.toPx()\n                    shape = RoundedCornerShape(8.dp)\n                    clip = false\n                }.clip(RoundedCornerShape(8.dp)).background(s.panel)\n                    .border(1.dp, s.text.copy(alpha = .17f), RoundedCornerShape(8.dp))) {\n                    Canvas(Modifier.fillMaxSize()) {\n                        val field = Offset(size.width * x, size.height * y)\n                        drawRect(Brush.linearGradient(listOf(s.panel, s.primary.copy(alpha = .65f), s.extra.copy(alpha = .6f), s.panel),\n                            start = Offset(-size.width * x, 0f), end = Offset(size.width * (1.3f - x), size.height)))\n                        // A deterministic guilloche pattern: the actual layers, not a downloaded image.\n                        repeat(19) { ring ->\n                            val shift = Offset((x - .5f) * 24.dp.toPx(), (y - .5f) * 20.dp.toPx())\n                            val hub = Offset(size.width * .60f, size.height * .34f) + shift\n                            val radius = size.width * (.14f + ring * .013f)\n                            val wave = Path()\n                            repeat(145) { step ->\n                                val angle = step * 2f * PI.toFloat() / 144\n                                val modulation = 1f + .14f * sin(angle * 7 + ring * .17f)\n                                val at = hub + Offset(cos(angle), sin(angle)) * radius * modulation\n                                if (step == 0) wave.moveTo(at.x, at.y) else wave.lineTo(at.x, at.y)\n                            }\n                            wave.close()\n                            drawPath(wave, s.text.copy(alpha = .12f + ring % 3 * .035f), style = Stroke(.55.dp.toPx()))\n                        }\n                        repeat(32) { line ->\n                            val at = line * size.width / 31\n                            drawLine(s.text.copy(alpha = .05f), Offset(at, 0f), Offset(at - size.height * .5f, size.height), .6.dp.toPx())\n                        }\n                        drawCircle(s.extra.copy(alpha = .24f), size.width * .14f, field)\n                    }\n                    Column(Modifier.fillMaxSize().padding(20.dp)) {\n                        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n                            Text(\"OPEN / STUDIO\", color = s.text, fontFamily = FontFamily.Monospace,\n                                fontWeight = FontWeight.Bold, fontSize = 9.sp, modifier = Modifier.weight(1f))\n                            Text(\"↗\", color = s.text, fontSize = 24.sp)\n                        }\n                        Text(\"ALL IDEAS\\nWELCOME\", Modifier.padding(top = 8.dp), color = s.text.copy(alpha = .6f),\n                            fontFamily = FontFamily.Monospace, fontSize = 8.sp, lineHeight = 12.sp)\n                        Spacer(Modifier.weight(1f))\n                        Text(\"入场。\\n用好奇心。\", Modifier.graphicsLayer {\n                            translationX = (x - .5f) * 12.dp.toPx()\n                            translationY = (y - .5f) * 10.dp.toPx()\n                        }, color = s.text, fontFamily = FontFamily.Serif,\n                            fontWeight = FontWeight.Bold, fontSize = 30.sp, lineHeight = 36.sp)\n                        Spacer(Modifier.height(18.dp))\n                        Canvas(Modifier.fillMaxWidth().height(22.dp)) {\n                            // Decorative print bars; no encoded personal data or access credential.\n                            var pos = 0f\n                            repeat(42) { index ->\n                                val width = (if (index % 3 == 0) 2.3f else .8f).dp.toPx()\n                                drawRect(s.text, Offset(pos, 0f), Size(width, size.height * if (index % 4 == 0) 1f else .75f))\n                                pos += width + 1.6.dp.toPx()\n                            }\n                        }\n                        Text(\"\${p.value} / VISITOR\", Modifier.padding(top = 7.dp), color = s.text,\n                            fontFamily = FontFamily.Monospace, fontSize = 8.sp, letterSpacing = .8.sp)\n                    }\n                    Canvas(Modifier.fillMaxSize()) {\n                        // getValues uses atan2(dx, -dy), then rotates a vertical glare gradient.\n                        val angle = atan2((x - .5f) * size.width, -(y - .5f) * size.height)\n                        val direction = Offset(sin(angle), -cos(angle))\n                        val extent = size.maxDimension\n                        val bright = center + direction * extent * .7f\n                        drawRect(Brush.linearGradient(listOf(Color.Transparent, Color.White.copy(alpha = y * .32f)),\n                            start = center - direction * extent * .2f, end = bright))\n                    }\n                }\n            }\n        }\n        Text(\"拖动改变视角，松手回正。也可以点选观察角度。\", color = s.text.copy(alpha = .65f),\n            fontSize = 11.sp, lineHeight = 17.sp)\n        val options = listOf(\"左侧\", \"正面\", \"右侧\")\n        val button: @Composable (Int, Modifier) -> Unit = { index, modifier ->\n            TextButton(onClick = { touchX = listOf(.12f, .5f, .88f)[index]; touchY = if (index == 1) .5f else .7f },\n                enabled = interactive, modifier = modifier.heightIn(min = 48.dp),\n                colors = ButtonDefaults.textButtonColors(contentColor = s.text, disabledContentColor = s.text.copy(alpha = .5f))) {\n                Text(options[index], fontSize = 12.sp)\n            }\n        }\n        if (fontScale > 1.7f) Column(Modifier.fillMaxWidth()) {\n            options.indices.forEach { button(it, Modifier.fillMaxWidth()) }\n        } else Row(Modifier.fillMaxWidth()) { options.indices.forEach { button(it, Modifier.weight(1f)) } }\n    }\n}\n\n/** Paired angles from upstream getValues(), bounded independently on both axes. */\nprivate fun FoiltiltAngles(x: Float, y: Float): Pair<Float, Float> =\n    (18f - x.coerceIn(0f, 1f) * 36f) to (y.coerceIn(0f, 1f) * 36f - 18f)",
        "depthstack" to "/**\n * Adapted from Ramotion/expanding-collection-android, MIT, Copyright (c) 2017 Ramotion.\n * https://github.com/Ramotion/expanding-collection-android/blob/07ca505e41db1c8d6972731df8834e236dd232c1/expanding-collection/src/main/java/com/ramotion/expandingcollection/AlphaScalePageTransformer.java\n * https://github.com/Ramotion/expanding-collection-android/blob/07ca505e41db1c8d6972731df8834e236dd232c1/expanding-collection/src/main/java/com/ramotion/expandingcollection/ECPagerCard.java\n * Retains inactive scale=.8, alpha=.5 and the neighbor-push / delayed expand\n * choreography (200 ms, 150 ms delay, 250 ms). Replaces ViewPager, bitmap caching,\n * adapters and full-screen expansion with three original layered terrain studies.\n * Adds bounded Compose graphics, 48 dp navigation and a static thumbnail.\n * Credit: https://www.ramotion.com\n */\n@Composable\nprivate fun StyleDepthstack(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var selected by rememberSaveable { mutableIntStateOf(1) }\n    var expanded by rememberSaveable { mutableStateOf(false) }\n    val position = remember { Animatable(selected.toFloat()) }\n    val push = remember { Animatable(0f) }\n    val reveal = remember { Animatable(0f) }\n    val names = listOf(\"峡谷\", \"丘陵\", \"海湾\")\n    val codes = listOf(\"CANYON / SEDIMENT\", \"HILLS / TERRAIN\", \"COAST / TIDELINE\")\n    LaunchedEffect(selected, interactive) {\n        if (interactive) position.animateTo(selected.toFloat(), tween(420, easing = FastOutSlowInEasing))\n    }\n    LaunchedEffect(expanded, interactive) {\n        if (!interactive) return@LaunchedEffect\n        if (expanded) {\n            launch { push.animateTo(1f, tween(200)) }\n            delay(150)\n            reveal.animateTo(1f, tween(250, easing = FastOutSlowInEasing))\n        } else {\n            launch { reveal.animateTo(0f, tween(250, easing = FastOutSlowInEasing)) }\n            delay(150)\n            push.animateTo(0f, tween(200))\n        }\n    }\n    val amount = if (interactive) reveal.value else 0f\n    val moving = push.isRunning || reveal.isRunning || position.isRunning\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(vertical = 18.dp)) {\n        Column(Modifier.padding(horizontal = 18.dp)) {\n            Text(\"STRATA / COLLECTION\", color = s.text.copy(alpha = .65f), fontSize = 9.sp,\n                letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n            Text(\"把风景，拆成几层\", Modifier.padding(top = 8.dp), color = s.text,\n                fontSize = 25.sp, lineHeight = 33.sp, fontWeight = FontWeight.Bold)\n        }\n        BoxWithConstraints(Modifier.fillMaxWidth().height((278 + amount * 88).dp).clipToBounds()) {\n            val baseWidth = maxWidth * .73f\n            val paneWidth = baseWidth + (maxWidth - 36.dp - baseWidth) * amount\n            val density = LocalDensity.current\n            val stride = with(density) { (baseWidth * .88f).toPx() }\n            val pushWidth = with(density) { maxWidth.toPx() * .68f }\n            val center = if (interactive) position.value else selected.toFloat()\n            listOf(0, 1, 2).forEach { index ->\n                val distance = index - center\n                val closeness = (1f - abs(distance)).coerceIn(0f, 1f)\n                val active = index == selected\n                Box(Modifier.align(Alignment.Center).width(if (active) paneWidth else baseWidth)\n                    .height((244 + if (active) amount * 88 else 0f).dp)\n                    .zIndex(closeness)\n                    .graphicsLayer {\n                        translationX = distance * (stride + pushWidth * (if (interactive) push.value else 0f))\n                        val scale = .8f + .2f * closeness\n                        scaleX = scale\n                        scaleY = scale\n                        alpha = (.5f + .5f * closeness) * (if (active) 1f else 1f - amount * .85f)\n                    }\n                    .clip(RoundedCornerShape(5.dp)).background(s.panel)\n                    .border(1.dp, s.text.copy(alpha = .16f), RoundedCornerShape(5.dp))\n                    .clickable(enabled = interactive && !expanded && !moving, role = Role.Button,\n                        onClickLabel = if (active) \"展开\${names[index]}分层\" else \"选择\${names[index]}\") {\n                        if (active) expanded = true else selected = index\n                    }.then(if (expanded && !active) Modifier.clearAndSetSemantics { }\n                        else Modifier.semantics { contentDescription = \"\${names[index]}地貌标本\" })) {\n                    Column(Modifier.fillMaxSize()) {\n                        Row(Modifier.fillMaxWidth().padding(13.dp), horizontalArrangement = Arrangement.SpaceBetween) {\n                            Text(\"0\${index + 1} / \${names[index]}\", color = s.text, fontSize = 14.sp,\n                                fontWeight = FontWeight.SemiBold, modifier = Modifier.weight(1f), maxLines = 1, overflow = TextOverflow.Ellipsis)\n                            Text(\"↗\", color = s.primary, fontSize = 17.sp)\n                        }\n                        Canvas(Modifier.fillMaxWidth().weight(1f)) {\n                            val explode = if (active) amount else 0f\n                            val base = when (index) { 0 -> s.primary; 1 -> s.extra; else -> Color(0xFF6E9CA1) }\n                            drawRect(lerp(s.panel, base, .13f))\n                            drawCircle(s.panel, size.width * .13f, Offset(size.width * .77f, size.height * .2f))\n                            repeat(5) { layer ->\n                                val y = size.height * (.42f + layer * .105f - explode * .12f)\n                                val peak = size.height * (.18f - layer * .021f)\n                                val bottom = size.height * (1f - explode) + (y + size.height * .07f) * explode\n                                val phase = index * .2f + layer * .12f\n                                val path = Path().apply {\n                                    moveTo(0f, y)\n                                    cubicTo(size.width * .16f, y - peak * (1f + phase), size.width * .26f, y - peak * .2f, size.width * .42f, y - peak * .65f)\n                                    cubicTo(size.width * .6f, y - peak * (index + .45f), size.width * .83f, y - peak * .12f, size.width, y - peak * .5f)\n                                    lineTo(size.width, bottom); lineTo(0f, bottom); close()\n                                }\n                                drawPath(path, lerp(base, s.text, layer * .14f))\n                                if (explode > .3f) {\n                                    drawLine(s.text.copy(alpha = .22f * explode), Offset(size.width * .08f, bottom + 2.dp.toPx()),\n                                        Offset(size.width * .24f, bottom + 2.dp.toPx()), 1.dp.toPx())\n                                }\n                            }\n                            if (explode > 0f) {\n                                val x = size.width - 12.dp.toPx()\n                                drawLine(s.text.copy(alpha = .35f * explode), Offset(x, size.height * .3f), Offset(x, size.height * .9f), 1.dp.toPx())\n                                repeat(5) { i ->\n                                    val y = size.height * (.34f + i * .12f)\n                                    drawLine(s.text.copy(alpha = .5f * explode), Offset(x - 4.dp.toPx(), y), Offset(x, y), 1.dp.toPx())\n                                }\n                            }\n                        }\n                        Text(codes[index], Modifier.padding(horizontal = 13.dp, vertical = 12.dp), color = s.text.copy(alpha = .7f),\n                            fontSize = 8.sp, fontFamily = FontFamily.Monospace, maxLines = 1, overflow = TextOverflow.Ellipsis)\n                    }\n                }\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(horizontal = 18.dp), verticalAlignment = Alignment.CenterVertically,\n            horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            Box(Modifier.size(48.dp).border(1.dp, s.text.copy(alpha = .25f), CircleShape)\n                .clickable(enabled = interactive && !expanded && !moving, role = Role.Button, onClickLabel = \"上一处地貌\") { selected = (selected + 2) % 3 }\n                .semantics { contentDescription = \"上一处地貌\" }, contentAlignment = Alignment.Center) {\n                Text(\"←\", color = s.text.copy(alpha = if (expanded) .3f else 1f), fontSize = 18.sp)\n            }\n            Button(onClick = { expanded = !expanded }, enabled = interactive && !moving,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp).semantics { stateDescription = if (expanded) \"分层展开\" else \"合拢预览\" },\n                shape = RoundedCornerShape(4.dp), colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg,\n                    disabledContainerColor = s.text, disabledContentColor = s.bg)) {\n                Text(if (expanded) \"合拢标本\" else \"展开层次\", fontSize = 12.sp)\n            }\n            Box(Modifier.size(48.dp).border(1.dp, s.text.copy(alpha = .25f), CircleShape)\n                .clickable(enabled = interactive && !expanded && !moving, role = Role.Button, onClickLabel = \"下一处地貌\") { selected = (selected + 1) % 3 }\n                .semantics { contentDescription = \"下一处地貌\" }, contentAlignment = Alignment.Center) {\n                Text(\"→\", color = s.text.copy(alpha = if (expanded) .3f else 1f), fontSize = 18.sp)\n            }\n        }\n        Text(if (expanded) \"五层地貌，在同一张切片里展开\" else \"左右选择地貌，展开观察内部层次\", Modifier.padding(horizontal = 18.dp).padding(top = 12.dp),\n            color = s.text.copy(alpha = .6f), fontSize = 10.sp, lineHeight = 16.sp)\n    }\n}",
        "flapcounter" to "/**\n * Adapted from absswds/FlipClock, MIT, Copyright (c) 2026 absswds.\n * https://github.com/absswds/FlipClock/blob/4b9b714811fbcb8a6f2e0490a122ce923781a15f/app/src/main/java/com/binbi/flipclock/clock/flip/FlipGlyph.kt\n * https://github.com/absswds/FlipClock/blob/4b9b714811fbcb8a6f2e0490a122ce923781a15f/app/src/main/java/com/binbi/flipclock/clock/flip/UnitFlipCard.kt\n * Retains full-height measurement of half panels, a 90-degree face swap, hinge\n * transform origins and the 180-degree hand-off to one clean resting glyph.\n * Replaces the clock, fonts, theme classes and shadow helpers with an original\n * manual counter, system monospace, short gradients, accessible controls and\n * finite on-demand animations. No dates, ticking, external assets or API26 calls.\n */\n@Composable\nprivate fun StyleFlapcounter(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var count by rememberSaveable { mutableIntStateOf(24) }\n    var shownCount by remember { mutableIntStateOf(count) }\n    var previousCount by remember { mutableIntStateOf(count) }\n    val targetCount by rememberUpdatedState(count)\n    val rotation = remember { Animatable(180f) }\n    LaunchedEffect(interactive) {\n        rotation.snapTo(180f)\n        if (!interactive) {\n            shownCount = targetCount\n            previousCount = targetCount\n            return@LaunchedEffect\n        }\n        // Both digits share one hand-off so a carry never mixes separate targets.\n        // Finish that flip, then consume only the latest of at most one waiting count.\n        snapshotFlow { targetCount }.conflate().collect { target ->\n            if (target != shownCount) {\n                rotation.snapTo(0f)\n                previousCount = shownCount\n                shownCount = target\n                rotation.animateTo(180f, tween(620, easing = FastOutSlowInEasing))\n            }\n        }\n    }\n    val faceCount = if (interactive) shownCount else count\n    val backCount = if (interactive) previousCount else count\n    val angle = if (interactive) rotation.value else 180f\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(\"MECHANICAL / COUNTING ROOM\", color = s.text.copy(alpha = .65f), fontSize = 9.sp,\n            letterSpacing = .7.sp, fontFamily = FontFamily.Monospace)\n        Text(\"让数字，有机械感\", Modifier.padding(top = 8.dp), color = s.text, fontSize = 25.sp,\n            lineHeight = 33.sp, fontWeight = FontWeight.Bold)\n        Row(Modifier.fillMaxWidth().padding(top = 18.dp, bottom = 12.dp), horizontalArrangement = Arrangement.SpaceBetween) {\n            Text(\"COUNTER 01\", color = s.primary, fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n            Text(\"00—99\", color = s.text.copy(alpha = .55f), fontSize = 10.sp, fontFamily = FontFamily.Monospace)\n        }\n        BoxWithConstraints(Modifier.fillMaxWidth().height(186.dp).clearAndSetSemantics { contentDescription = \"当前计数 \$count 次\" }) {\n            val width = (maxWidth - 10.dp) / 2\n            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n                FlapcounterDigit(backCount / 10, faceCount / 10, angle, s, width, 186.dp)\n                FlapcounterDigit(backCount % 10, faceCount % 10, angle, s, width, 186.dp)\n            }\n            Canvas(Modifier.fillMaxSize()) {\n                drawLine(s.bg, Offset(0f, center.y), Offset(size.width, center.y), 3.dp.toPx())\n                drawLine(s.text.copy(alpha = .11f), Offset(0f, center.y + 2.dp.toPx()), Offset(size.width, center.y + 2.dp.toPx()), 1.dp.toPx())\n                listOf(3.dp.toPx(), size.width - 3.dp.toPx()).forEach { x ->\n                    drawRoundRect(s.primary, Offset(x - 2.dp.toPx(), center.y - 9.dp.toPx()), Size(4.dp.toPx(), 18.dp.toPx()), CornerRadius(2.dp.toPx()))\n                }\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 16.dp), verticalAlignment = Alignment.CenterVertically) {\n            Text(\"已记录 \$count 次\", color = s.text, fontSize = 12.sp, modifier = Modifier.weight(1f))\n            Canvas(Modifier.width(58.dp).height(12.dp)) {\n                repeat(7) { i ->\n                    drawCircle(if (((count shr i) and 1) == 1) s.primary else s.text.copy(alpha = .14f),\n                        2.dp.toPx(), Offset(size.width * (i + .5f) / 7f, center.y))\n                }\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 18.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            Box(Modifier.size(48.dp).clip(RoundedCornerShape(5.dp)).background(s.panel)\n                .clickable(enabled = interactive && count > 0, role = Role.Button, onClickLabel = \"计数减一\") { count-- }\n                .semantics { contentDescription = \"计数减一\" }, contentAlignment = Alignment.Center) {\n                Text(\"−\", color = s.text, fontSize = 22.sp)\n            }\n            Button(onClick = { count = (count + 1) % 100 }, enabled = interactive,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp), shape = RoundedCornerShape(5.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.primary, contentColor = s.bg,\n                    disabledContainerColor = s.primary, disabledContentColor = s.bg)) {\n                Text(\"记一次 +\", fontSize = 12.sp, fontWeight = FontWeight.Bold)\n            }\n            Box(Modifier.size(48.dp).clip(RoundedCornerShape(5.dp)).background(s.panel)\n                .clickable(enabled = interactive, role = Role.Button, onClickLabel = \"计数归零\") { count = 0 }\n                .semantics { contentDescription = \"计数归零\" }, contentAlignment = Alignment.Center) {\n                Text(\"↺\", color = s.text, fontSize = 22.sp)\n            }\n        }\n        Text(\"只有变化的数位，才会翻动\", Modifier.padding(top = 12.dp), color = s.text.copy(alpha = .6f), fontSize = 10.sp)\n    }\n}\n\n@Composable\nprivate fun FlapcounterDigit(previous: Int, shown: Int, angle: Float, s: CreativeStyleSpec, width: Dp, height: Dp) {\n    Box(Modifier.size(width, height).clip(RoundedCornerShape(7.dp)).border(1.dp, s.text.copy(alpha = .12f), RoundedCornerShape(7.dp))) {\n        if (angle >= 180f || previous == shown) {\n            FlapcounterFace(shown, s, width, height)\n        } else {\n            FlapcounterHalf(true, width, height, Modifier.align(Alignment.TopCenter)) { FlapcounterFace(shown, s, width, height) }\n            FlapcounterHalf(false, width, height, Modifier.align(Alignment.BottomCenter)) { FlapcounterFace(previous, s, width, height) }\n            if (angle < 90f) {\n                FlapcounterHalf(true, width, height, Modifier.align(Alignment.TopCenter).graphicsLayer {\n                    rotationX = -angle\n                    cameraDistance = 12f * density\n                    transformOrigin = TransformOrigin(.5f, 1f)\n                }) {\n                    Box(Modifier.size(width, height)) {\n                        FlapcounterFace(previous, s, width, height)\n                        Box(Modifier.matchParentSize().background(Color.Black.copy(alpha = angle / 90f * .32f)))\n                    }\n                }\n            } else {\n                FlapcounterHalf(false, width, height, Modifier.align(Alignment.BottomCenter).graphicsLayer {\n                    rotationX = -(180f - angle)\n                    cameraDistance = 12f * density\n                    transformOrigin = TransformOrigin(.5f, 0f)\n                }) {\n                    Box(Modifier.size(width, height)) {\n                        FlapcounterFace(shown, s, width, height)\n                        Box(Modifier.matchParentSize().background(Color.Black.copy(alpha = (180f - angle) / 90f * .32f)))\n                    }\n                }\n            }\n        }\n    }\n}\n\n@Composable\nprivate fun FlapcounterHalf(top: Boolean, width: Dp, height: Dp, modifier: Modifier, content: @Composable () -> Unit) {\n    Layout(content = content, modifier = modifier.clipToBounds()) { measurables, _ ->\n        val w = width.roundToPx()\n        val h = height.roundToPx()\n        val half = h / 2\n        val face = measurables.single().measure(Constraints.fixed(w, h))\n        layout(w, half) { face.place(0, if (top) 0 else -half) }\n    }\n}\n\n@Composable\nprivate fun FlapcounterFace(digit: Int, s: CreativeStyleSpec, width: Dp, height: Dp) {\n    // The numerals are diagram artwork; the outer counter semantics retain the full value.\n    val glyphSize = (width.value * 1.18f).coerceAtMost(142f) / LocalDensity.current.fontScale\n    Box(Modifier.size(width, height).background(Brush.verticalGradient(\n        listOf(lerp(s.panel, Color.White, .04f), s.panel, lerp(s.panel, Color.Black, .19f)))), contentAlignment = Alignment.Center) {\n        Text(digit.toString(), color = s.text, fontSize = glyphSize.sp, lineHeight = glyphSize.sp,\n            fontFamily = FontFamily.Monospace, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center,\n            modifier = Modifier.offset(y = (-6).dp), maxLines = 1)\n    }\n}",
        "liquidswipe" to "// Adapted from react-liquidswipe, Copyright (c) 2021 Ashutosh Hathidara (MIT).\n// https://github.com/ashutosh1919/react-liquidswipe/blob/678cb1fc21d5f0523f189e90347ba9ce483a7cb4/src/components/liquidswipe.js\n// Video: https://www.youtube.com/watch?v=uGoWVz-q2M8\n// Extracted: getPath's two cubic Beziers and drag-past-half / return interaction.\n// Changes: native Compose clipping + gestures; responsive geometry; three original\n// posters; next-page button; no React, SVG assets, package dependency or frame loop.\n// The complete upstream MIT license is in tools/creative/licenses/liquidswipe.txt.\n@Composable\nprivate fun StyleLiquidswipe(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var page by rememberSaveable { mutableIntStateOf(0) }\n    val titles = p.items.ifEmpty { listOf(p.headline) }\n    val index = if (interactive) page % titles.size else 0\n    val nextIndex = (index + 1) % titles.size\n    val motion = remember { Animatable(0f) }\n    val scope = rememberCoroutineScope()\n    var canvasSize by remember { mutableStateOf(IntSize.Zero) }\n    var pulling by remember { mutableStateOf(false) }\n    var pull by remember { mutableFloatStateOf(0f) }\n    var touchY by remember { mutableFloatStateOf(.58f) }\n    var settling by remember { mutableStateOf(false) }\n    val progress = if (!interactive) 0f else if (pulling) pull else motion.value\n    val fontScale = LocalDensity.current.fontScale\n\n    // The single event-driven animation also powers the accessible button.\n    // It is never launched by a thumbnail or by a periodic effect.\n    val finish: (Boolean) -> Unit = { advance ->\n        if (interactive && !settling) {\n            settling = true\n            scope.launch {\n                try {\n                    if (pulling) motion.snapTo(pull)\n                    pulling = false\n                    if (advance) {\n                        motion.animateTo(1f, tween(520, easing = FastOutSlowInEasing))\n                        page = (page + 1) % titles.size\n                        motion.snapTo(0f)\n                    } else {\n                        motion.animateTo(0f, spring(dampingRatio = .82f, stiffness = 260f))\n                    }\n                    touchY = .58f\n                } finally {\n                    settling = false\n                }\n            }\n        }\n    }\n\n    Column(Modifier.fillMaxWidth().background(s.bg)) {\n        Row(\n            Modifier.fillMaxWidth().padding(horizontal = 18.dp, vertical = 15.dp),\n            verticalAlignment = Alignment.CenterVertically,\n            horizontalArrangement = Arrangement.spacedBy(12.dp),\n        ) {\n            Canvas(Modifier.size(12.dp)) {\n                drawCircle(s.text, size.minDimension / 2)\n                drawCircle(s.bg, size.minDimension / 5)\n            }\n            Text(p.caption, Modifier.weight(1f), color = s.text, fontFamily = FontFamily.Monospace,\n                fontWeight = FontWeight.Bold, fontSize = 10.sp, letterSpacing = 1.sp)\n            Text(p.value, color = s.text, fontFamily = FontFamily.Monospace, fontSize = 10.sp)\n        }\n        BoxWithConstraints(Modifier.fillMaxWidth()) {\n            // Growing the paper with system text scale keeps the complete title visible.\n            val posterHeight = 360.dp * fontScale.coerceAtLeast(1f)\n            val titleSize = (maxWidth.value * .107f).coerceIn(28f, 42f).sp\n            val gestureModifier = if (interactive) Modifier.pointerInput(canvasSize) {\n                detectHorizontalDragGestures(\n                    onDragStart = { start ->\n                        if (!settling && canvasSize.width > 0 && start.x < canvasSize.width * .30f) {\n                            pull = 0f\n                            touchY = (start.y / canvasSize.height.coerceAtLeast(1)).coerceIn(.15f, .85f)\n                            pulling = true\n                        }\n                    },\n                    onHorizontalDrag = { change, amount ->\n                        if (pulling && !settling) {\n                            change.consume()\n                            pull = (pull + amount / canvasSize.width.coerceAtLeast(1)).coerceIn(0f, .92f)\n                            touchY = (change.position.y / canvasSize.height.coerceAtLeast(1)).coerceIn(.15f, .85f)\n                        }\n                    },\n                    onDragEnd = { if (pulling) finish(pull > .5f) },\n                    onDragCancel = { if (pulling) finish(false) },\n                )\n            } else Modifier\n\n            Box(Modifier.fillMaxWidth().height(posterHeight).clipToBounds()\n                .onSizeChanged { canvasSize = it }.then(gestureModifier)\n                .semantics {\n                    contentDescription = \"液态揭幕海报，\${titles[index]}\"\n                    stateDescription = \"第 \${index + 1} 张，共 \${titles.size} 张\"\n                }) {\n                StyleLiquidPoster(s, p, titles[index], index, titleSize,\n                    Modifier.fillMaxSize().clearAndSetSemantics { })\n                // Clip the next entire poster, including its typography, into the liquid edge.\n                StyleLiquidPoster(s, p, titles[nextIndex], nextIndex, titleSize,\n                    Modifier.fillMaxSize().clearAndSetSemantics { }.drawWithContent {\n                        clipPath(StyleLiquidRevealPath(size, progress, touchY)) { this@drawWithContent.drawContent() }\n                    })\n                Canvas(Modifier.fillMaxSize().clearAndSetSemantics { }) {\n                    val amount = progress.coerceIn(0f, 1f)\n                    val (edge, bulge) = StyleLiquidEdge(size.width, amount)\n                    val knob = Offset(edge + bulge * .55f, size.height * touchY)\n                    if (amount < .8f) {\n                        val radius = 18.dp.toPx()\n                        drawCircle(s.text, radius, knob, alpha = (1f - amount / .8f))\n                        val line = 5.dp.toPx()\n                        drawLine(s.bg, knob + Offset(-line, -line), knob + Offset(line, 0f), 1.5.dp.toPx())\n                        drawLine(s.bg, knob + Offset(line, 0f), knob + Offset(-line, line), 1.5.dp.toPx())\n                    }\n                }\n            }\n        }\n        Column(Modifier.fillMaxWidth().padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n            Text(p.headline, color = s.text, fontSize = 17.sp, fontFamily = s.font,\n                fontWeight = FontWeight.SemiBold, lineHeight = 23.sp)\n            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically,\n                horizontalArrangement = Arrangement.spacedBy(12.dp)) {\n                Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {\n                    Row(horizontalArrangement = Arrangement.spacedBy(5.dp)) {\n                        repeat(titles.size) { dot ->\n                            Box(Modifier.size(if (dot == index) 18.dp else 6.dp, 5.dp)\n                                .background(if (dot == index) s.text else s.text.copy(alpha = .2f), CircleShape))\n                        }\n                    }\n                    Text(\"从左侧向右拉，过半翻页\", color = s.text.copy(alpha = .65f),\n                        fontSize = 10.sp, lineHeight = 15.sp)\n                }\n                Button(\n                    onClick = { finish(true) }, enabled = interactive && !settling && !pulling,\n                    modifier = Modifier.heightIn(min = 48.dp)\n                        .semantics { contentDescription = \"下一张海报\" },\n                    shape = CircleShape,\n                    contentPadding = PaddingValues(horizontal = 17.dp, vertical = 10.dp),\n                    colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg,\n                        disabledContainerColor = s.text, disabledContentColor = s.bg),\n                ) {\n                    Text(\"\${p.action}  ↗\", fontSize = 12.sp, fontWeight = FontWeight.Bold)\n                }\n            }\n        }\n    }\n}\n\n/** Two-stage travel: pull out the blob first, then sweep the entire paper edge. */\nprivate fun StyleLiquidEdge(width: Float, progress: Float): Pair<Float, Float> {\n    val reveal = ((progress - .55f) / .45f).coerceIn(0f, 1f)\n    val restingBulge = width * .15f\n    val pulledBulge = restingBulge + width * progress.coerceAtMost(.55f) * 1.1f\n    return width * reveal to pulledBulge * (1f - reveal)\n}\n\n/** Port of upstream getPath; SVG smooth S is expanded to an explicit cubicTo. */\nprivate fun StyleLiquidRevealPath(size: Size, progress: Float, centerY: Float): Path {\n    val (edge, bulge) = StyleLiquidEdge(size.width, progress.coerceIn(0f, 1f))\n    val unit = size.width / 400f\n    val anchorDistance = 200f * unit + bulge * .5f\n    val curviness = anchorDistance - 60f * unit\n    val y = size.height * centerY\n    return Path().apply {\n        moveTo(0f, size.height)\n        lineTo(0f, 0f)\n        lineTo(edge, 0f)\n        lineTo(edge, y - anchorDistance)\n        cubicTo(edge, y - anchorDistance + curviness,\n            edge + bulge, y - anchorDistance + curviness, edge + bulge, y)\n        cubicTo(edge + bulge, y + anchorDistance - curviness,\n            edge, y, edge, y + anchorDistance * 2f)\n        lineTo(edge, size.height)\n        close()\n    }\n}\n\n@Composable\nprivate fun StyleLiquidPoster(\n    s: CreativeStyleSpec,\n    p: CreativePattern,\n    title: String,\n    index: Int,\n    titleSize: androidx.compose.ui.unit.TextUnit,\n    modifier: Modifier,\n) {\n    val paper = when (index % 3) { 0 -> s.bg; 1 -> s.primary; else -> s.extra }\n    val accent = when (index % 3) { 0 -> s.extra; 1 -> s.text; else -> s.bg }\n    Box(modifier.background(paper)) {\n        Canvas(Modifier.fillMaxSize()) {\n            val radius = size.width * .33f\n            val center = Offset(size.width * .83f, size.height * .38f)\n            val arcSize = Size(radius * 2, radius * 2)\n            repeat(4) { line ->\n                val inset = line * radius * .22f\n                drawArc(accent, -105f + index * 65f, 265f, false,\n                    center - Offset(radius - inset, radius - inset),\n                    Size(arcSize.width - inset * 2, arcSize.height - inset * 2),\n                    style = Stroke(size.width * .043f))\n            }\n            drawCircle(s.text, size.width * .024f, Offset(size.width * .46f, size.height * .55f))\n            drawLine(s.text.copy(alpha = .26f), Offset(size.width * .07f, size.height * .82f),\n                Offset(size.width * .93f, size.height * .82f), 1.dp.toPx())\n        }\n        Column(Modifier.fillMaxSize().padding(horizontal = 23.dp, vertical = 18.dp)) {\n            Text(\"0\${index + 1}\", color = s.text, fontSize = 91.sp, lineHeight = 94.sp,\n                fontFamily = FontFamily.SansSerif, fontWeight = FontWeight.Black, letterSpacing = (-7).sp)\n            Text(\"\${p.caption.substringBefore('/').trim()} / STUDY\", color = s.text,\n                fontFamily = FontFamily.Monospace, fontSize = 9.sp, letterSpacing = 2.sp)\n            Spacer(Modifier.weight(1f))\n            Text(title, color = s.text, fontSize = titleSize, lineHeight = titleSize * 1.12f,\n                fontFamily = s.font, fontWeight = FontWeight.Black,\n                modifier = Modifier.fillMaxWidth().padding(bottom = 23.dp))\n            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween,\n                verticalAlignment = Alignment.CenterVertically) {\n                Text(\"PULL.\\nREVEAL.\\nREPEAT.\", color = s.text, fontFamily = FontFamily.Monospace,\n                    fontSize = 9.sp, lineHeight = 12.sp, fontWeight = FontWeight.Bold)\n                Text(\"↗\", color = s.text, fontSize = 35.sp)\n            }\n        }\n    }\n}",
        "elasticnav" to "/**\n * Adapted from Exyte AndroidAnimatedNavigationBar, MIT, Copyright (c) 2023 Exyte.\n * Source revision: cc65ebd1f8644d8fa173a3cad0a935a050b0e961\n * https://github.com/exyte/AndroidAnimatedNavigationBar/blob/cc65ebd1f8644d8fa173a3cad0a935a050b0e961/animatednavbar/src/main/java/com/exyte/animatednavbar/shape/IndentPath.kt\n * https://github.com/exyte/AndroidAnimatedNavigationBar/blob/cc65ebd1f8644d8fa173a3cad0a935a050b0e961/animatednavbar/src/main/java/com/exyte/animatednavbar/animation/balltrajectory/Parabolic.kt\n * Changes: retains the two normalized cubic indent segments; evaluates a quadratic\n * jump directly instead of Android PathMeasure. Adds four original Canvas tools,\n * responsive bounds, tab semantics, and a static non-interactive preview.\n */\n@Composable\nprivate fun StyleElasticnav(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var selected by rememberSaveable { mutableIntStateOf(0) }\n    val names = listOf(\"构图\", \"色彩\", \"轨迹\", \"纹理\")\n    val subtitles = listOf(\"SHAPE THE UNEXPECTED\", \"COLOR OUTSIDE THE LINES\", \"FOLLOW YOUR OWN ORBIT\", \"MAKE A LITTLE NOISE\")\n    val position = remember { Animatable(selected.toFloat()) }\n    val flight = remember { Animatable(1f) }\n    val colors = listOf(s.primary, s.extra, Color(0xFF8ECAC0), Color(0xFFB8AAF0))\n    val sceneColor = colors[selected]\n    val sceneInk = if (.2126f * sceneColor.red + .7152f * sceneColor.green + .0722f * sceneColor.blue > .58f) Color(0xFF171D1C) else Color(0xFFFFFCF5)\n    LaunchedEffect(selected, interactive) {\n        if (!interactive || position.value == selected.toFloat()) return@LaunchedEffect\n        flight.snapTo(0f)\n        coroutineScope {\n            launch { position.animateTo(selected.toFloat(), tween(560, easing = FastOutSlowInEasing)) }\n            launch { flight.animateTo(1f, tween(560, easing = FastOutSlowInEasing)) }\n        }\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(\"ELASTIC / CREATIVE TOOLS\", color = s.text.copy(alpha = .65f),\n            fontSize = 9.sp, letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n        Row(Modifier.fillMaxWidth().padding(top = 8.dp), verticalAlignment = Alignment.Bottom) {\n            Text(\"让灵感，跳一下\", color = s.text, fontSize = 25.sp, lineHeight = 33.sp,\n                fontWeight = FontWeight.Bold, modifier = Modifier.weight(1f))\n            Text(\"0\${selected + 1}\", color = s.text.copy(alpha = .5f), fontSize = 15.sp,\n                fontFamily = FontFamily.Monospace, modifier = Modifier.padding(start = 8.dp, bottom = 4.dp))\n        }\n        Box(Modifier.fillMaxWidth().padding(top = 16.dp).height(176.dp).clip(RoundedCornerShape(16.dp)).background(sceneColor)) {\n            Canvas(Modifier.fillMaxSize().semantics { contentDescription = \"\${names[selected]}工具的抽象图形预览\" }) {\n                val c = Offset(size.width * .53f, size.height * .47f)\n                val r = size.minDimension * .33f\n                when (selected) {\n                    0 -> {\n                        drawCircle(sceneInk, r, c)\n                        drawRect(sceneColor, Offset(c.x - r, c.y - r * .25f), Size(r * 2, r * .5f))\n                        drawRect(sceneInk, Offset(c.x - r * .25f, c.y - r), Size(r * .5f, r * 2))\n                        drawCircle(sceneColor, r * .3f, c)\n                    }\n                    1 -> {\n                        repeat(5) { i ->\n                            rotate(i * 72f, c) {\n                                drawOval(if (i % 2 == 0) sceneInk else s.bg,\n                                    Offset(c.x - r * .28f, c.y - r * 1.04f), Size(r * .56f, r * 1.35f))\n                            }\n                        }\n                        drawCircle(sceneColor, r * .22f, c)\n                    }\n                    2 -> {\n                        repeat(6) { i ->\n                            rotate(-28f + i * 12f, c) {\n                                drawOval(sceneInk, Offset(c.x - r, c.y - r * .5f), Size(r * 2, r), style = Stroke(1.3.dp.toPx()))\n                            }\n                        }\n                        drawCircle(sceneInk, r * .14f, c + Offset(r * .83f, -r * .23f))\n                    }\n                    else -> repeat(9) { i ->\n                        val x = c.x - r + i * r / 4\n                        val path = Path().apply {\n                            moveTo(x, c.y - r)\n                            cubicTo(x - r * .65f, c.y - r * .25f, x + r * .65f, c.y + r * .25f, x, c.y + r)\n                        }\n                        drawPath(path, sceneInk, style = Stroke(2.dp.toPx()))\n                    }\n                }\n            }\n            Text(subtitles[selected], Modifier.align(Alignment.BottomStart).padding(12.dp), color = sceneInk,\n                fontFamily = FontFamily.Monospace, fontSize = 8.sp, letterSpacing = .8.sp,\n                maxLines = 1, overflow = TextOverflow.Ellipsis)\n        }\n        Box(Modifier.fillMaxWidth().height(126.dp)) {\n            Canvas(Modifier.fillMaxSize()) {\n                val slot = size.width / 4\n                val active = if (interactive) position.value else selected.toFloat()\n                val centerX = slot * (active + .5f)\n                val baseline = 50.dp.toPx()\n                val notchWidth = slot.coerceAtMost(76.dp.toPx())\n                val depth = 28.dp.toPx()\n                val left = centerX - notchWidth / 2\n                fun nx(value: Float) = left + value / 110f * notchWidth\n                fun ny(value: Float) = baseline + value / 34f * depth\n                val bar = Path().apply {\n                    moveTo(0f, baseline)\n                    lineTo(nx(0f), ny(0f))\n                    cubicTo(nx(23f), ny(0f), nx(39f), ny(34f), nx(55f), ny(34f))\n                    cubicTo(nx(71f), ny(34f), nx(87f), ny(0f), nx(110f), ny(0f))\n                    lineTo(size.width, baseline)\n                    lineTo(size.width, size.height)\n                    lineTo(0f, size.height)\n                    close()\n                }\n                drawPath(bar, s.panel)\n                repeat(4) { index ->\n                    if (index != selected) elasticnavGlyph(index, Offset(slot * (index + .5f), 78.dp.toPx()), 9.dp.toPx(), s.text.copy(alpha = .6f))\n                }\n                // Quadratic Bézier height: endpoints are level, control point rises above them.\n                val t = if (interactive) flight.value else 1f\n                val jump = 2f * (1f - t) * t * 56.dp.toPx()\n                val ball = Offset(centerX, baseline - 4.dp.toPx() - jump)\n                drawCircle(sceneColor, 20.dp.toPx(), ball)\n                elasticnavGlyph(selected, ball, 9.dp.toPx(), sceneInk)\n            }\n            Row(Modifier.fillMaxWidth().align(Alignment.BottomCenter)) {\n                names.forEachIndexed { index, label ->\n                    Box(Modifier.weight(1f).heightIn(min = 76.dp)\n                        .selectable(selected = selected == index, enabled = interactive, role = Role.Tab,\n                            onClick = { selected = index })\n                        .semantics { contentDescription = \"\${label}工具\" }\n                        .padding(horizontal = 2.dp, vertical = 9.dp), contentAlignment = Alignment.BottomCenter) {\n                        Text(label, color = s.text.copy(alpha = if (selected == index) 1f else .6f),\n                            fontSize = 11.sp, fontWeight = if (selected == index) FontWeight.Bold else FontWeight.Normal,\n                            maxLines = 1, overflow = TextOverflow.Ellipsis)\n                    }\n                }\n            }\n        }\n        Text(\"点选工具，球体与凹槽一起响应\", Modifier.padding(top = 10.dp), color = s.text.copy(alpha = .6f), fontSize = 10.sp)\n    }\n}\n\nprivate fun DrawScope.elasticnavGlyph(index: Int, center: Offset, radius: Float, color: Color) {\n    val line = 1.8.dp.toPx()\n    when (index) {\n        0 -> drawRect(color, center - Offset(radius * .7f, radius * .7f), Size(radius * 1.4f, radius * 1.4f), style = Stroke(line))\n        1 -> {\n            drawCircle(color, radius * .7f, center + Offset(-radius * .3f, 0f), style = Stroke(line))\n            drawCircle(color, radius * .7f, center + Offset(radius * .3f, 0f), style = Stroke(line))\n        }\n        2 -> {\n            drawOval(color, center - Offset(radius, radius * .5f), Size(radius * 2f, radius), style = Stroke(line))\n            drawCircle(color, line, center + Offset(radius * .7f, -radius * .35f))\n        }\n        else -> repeat(3) { i ->\n            val x = center.x + (i - 1) * radius * .65f\n            drawLine(color, Offset(x - radius * .25f, center.y + radius * .7f),\n                Offset(x + radius * .25f, center.y - radius * .7f), line, StrokeCap.Round)\n        }\n    }\n}",
        "paperfold" to "/**\n * Adapted from oleksandrbalan/pagecurl, Apache License 2.0.\n * Source revision: a390c64508abfc45379070a40591ba3ed0cc686e\n * https://github.com/oleksandrbalan/pagecurl/blob/a390c64508abfc45379070a40591ba3ed0cc686e/pagecurl/src/main/kotlin/eu/wewox/pagecurl/page/CurlDraw.kt\n * Changes: reduces the curl to two original printed pages and a bounded crease.\n * Retains front clipping plus mirrored/rotated back-page drawing; removes paging,\n * bitmap shadows, Android Canvas and API-specific branches. Adds horizontal drag,\n * an accessible flip button, cancellation recovery, and a static folded preview.\n */\n@Composable\nprivate fun StylePaperfold(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var page by rememberSaveable { mutableIntStateOf(0) }\n    var progress by remember { mutableFloatStateOf(if (interactive) 0f else .24f) }\n    var tilt by remember { mutableFloatStateOf(.12f) }\n    var widthPx by remember { mutableFloatStateOf(1f) }\n    var settling by remember { mutableStateOf(false) }\n    var settleJob by remember { mutableStateOf<Job?>(null) }\n    val scope = rememberCoroutineScope()\n    fun settle(turn: Boolean) {\n        settleJob?.cancel()\n        settling = true\n        settleJob = scope.launch {\n            val motion = Animatable(progress)\n            motion.animateTo(if (turn) 1f else 0f, tween(460, easing = FastOutSlowInEasing)) {\n                progress = value\n            }\n            if (turn) page = 1 - page\n            progress = 0f\n            settling = false\n        }\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(\"PAPER / IN MOTION\", color = s.text.copy(alpha = .65f), fontSize = 9.sp,\n            letterSpacing = 1.sp, fontFamily = FontFamily.Monospace)\n        Text(\"翻开另一种可能\", color = s.text, fontSize = 25.sp, lineHeight = 33.sp,\n            fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 8.dp, bottom = 16.dp))\n        val drag = if (interactive) Modifier.pointerInput(page, widthPx) {\n            var startY = 0f\n            detectHorizontalDragGestures(\n                onDragStart = { point ->\n                    settleJob?.cancel()\n                    settling = false\n                    startY = point.y\n                },\n                onHorizontalDrag = { change, amount ->\n                    change.consume()\n                    progress = (progress - amount / widthPx).coerceIn(0f, 1f)\n                    tilt = ((change.position.y - startY) / size.height.coerceAtLeast(1) + .12f).coerceIn(-.25f, .25f)\n                },\n                onDragEnd = { settle(progress > .35f) },\n                onDragCancel = { settle(false) },\n            )\n        } else Modifier\n        Box(Modifier.fillMaxWidth().height(286.dp)\n            .onSizeChanged { widthPx = it.width.toFloat().coerceAtLeast(1f) }\n            .clip(RoundedCornerShape(2.dp)).border(1.dp, s.text.copy(alpha = .15f))\n            .then(drag).semantics {\n                contentDescription = \"可折叠的双页印刷海报，向左拖动翻页\"\n                stateDescription = \"第 \${page + 1} 页，共 2 页\"\n            }) {\n            PaperfoldSheet(s, 1 - page, Modifier.fillMaxSize())\n            PaperfoldSheet(s, page, Modifier.fillMaxSize().paperfoldCurl(\n                progress = { progress }, tilt = { tilt }, backColor = s.panel, ink = s.text))\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 14.dp), verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f).padding(end = 12.dp)) {\n                Text(\"0\${page + 1} / 02\", color = s.text, fontSize = 11.sp, fontFamily = FontFamily.Monospace)\n                Text(\"向左轻推纸面\", color = s.text.copy(alpha = .6f), fontSize = 10.sp, modifier = Modifier.padding(top = 4.dp))\n            }\n            Button(onClick = { if (interactive && !settling) settle(true) }, enabled = interactive && !settling,\n                modifier = Modifier.heightIn(min = 48.dp).semantics { contentDescription = \"翻到另一页\" }, shape = RoundedCornerShape(2.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg,\n                    disabledContainerColor = s.text, disabledContentColor = s.bg)) {\n                Text(if (settling) \"翻页中\" else \"翻页 ↗\", fontSize = 11.sp)\n            }\n        }\n    }\n}\n\n@Composable\nprivate fun PaperfoldSheet(s: CreativeStyleSpec, page: Int, modifier: Modifier) {\n    val paper = if (page == 0) s.panel else s.primary\n    val ink = if (page == 0) s.text else s.panel\n    Column(modifier.background(paper).padding(16.dp)) {\n        Text(if (page == 0) \"EDITION 01 / THE FOLD\" else \"EDITION 02 / THE OTHER SIDE\", color = ink,\n            fontSize = 8.sp, letterSpacing = 1.sp, fontFamily = FontFamily.Monospace,\n            maxLines = 1, overflow = TextOverflow.Ellipsis)\n        Text(if (page == 0) \"纸上\\n有风。\" else \"背面\\n有光。\", color = ink,\n            fontSize = 33.sp, lineHeight = 35.sp, fontWeight = FontWeight.Black,\n            modifier = Modifier.padding(top = 10.dp), maxLines = 2, overflow = TextOverflow.Ellipsis)\n        Canvas(Modifier.fillMaxWidth().weight(1f).padding(vertical = 9.dp)) {\n            val radius = size.minDimension * .43f\n            if (radius > 0f) {\n                val center = Offset(size.width * .58f, size.height * .5f)\n                if (page == 0) {\n                    drawCircle(s.primary, radius, center)\n                    repeat(7) { i ->\n                        val y = center.y - radius + i * radius / 3\n                        drawLine(s.text, Offset(center.x - radius * 1.4f, y), Offset(center.x + radius * .65f, y), 1.3.dp.toPx())\n                    }\n                } else {\n                    repeat(8) { i ->\n                        rotate(i * 22.5f, center) {\n                            drawOval(s.panel, center - Offset(radius, radius * .3f), Size(radius * 2, radius * .6f), style = Stroke(1.3.dp.toPx()))\n                        }\n                    }\n                    drawCircle(s.text, radius * .25f, center)\n                }\n            }\n        }\n        Text(if (page == 0) \"A SMALL ACT OF CURIOSITY.\" else \"THERE IS ALWAYS ANOTHER WAY.\", color = ink,\n            fontSize = 8.sp, fontFamily = FontFamily.Monospace, maxLines = 1, overflow = TextOverflow.Ellipsis)\n    }\n}\n\nprivate fun Modifier.paperfoldCurl(progress: () -> Float, tilt: () -> Float, backColor: Color, ink: Color): Modifier = drawWithContent {\n    val amount = progress().coerceIn(0f, 1f)\n    if (amount <= .001f) {\n        drawContent()\n    } else if (amount < .999f) {\n        val creaseX = size.width * (1f - amount)\n        val skew = sin(amount * PI).toFloat() * tilt() * size.width\n        val top = Offset((creaseX + skew).coerceIn(0f, size.width), 0f)\n        val bottom = Offset((creaseX - skew).coerceIn(0f, size.width), size.height)\n        val front = Path().apply {\n            moveTo(0f, 0f); lineTo(top.x, top.y); lineTo(bottom.x, bottom.y); lineTo(0f, size.height); close()\n        }\n        clipPath(front) { this@drawWithContent.drawContent() }\n        val back = Path().apply {\n            moveTo(top.x, top.y); lineTo(size.width, 0f); lineTo(size.width, size.height); lineTo(bottom.x, bottom.y); close()\n        }\n        val line = top - bottom\n        val angle = PI.toFloat() - atan2(line.y, line.x) * 2f\n        // These transforms and the back-page clip are the retained Page Curl core.\n        withTransform({\n            scale(-1f, 1f, pivot = bottom)\n            rotateRad(angle, pivot = bottom)\n        }) {\n            clipPath(back) {\n                this@drawWithContent.drawContent()\n                drawRect(backColor.copy(alpha = .9f))\n                drawRect(Brush.horizontalGradient(listOf(ink.copy(alpha = .14f), Color.Transparent), startX = top.x, endX = size.width.coerceAtLeast(top.x + 1f)))\n            }\n        }\n        drawLine(ink.copy(alpha = .24f), top, bottom, .8.dp.toPx())\n    }\n}",
        "scratchmap" to "// Adapted from AdamDawi/ScratchCardCompose, MIT, Copyright (c) 2025 Adam Dawidziuk.\n// https://github.com/AdamDawi/ScratchCardCompose/blob/162cfd3ea38e5da60a8d9564b690b0174bbb9a4a/app/src/main/java/com/example/scratchcardcompose/ui/scratch_card/ScratchCard.kt\n// Retained: an isolated offscreen overlay and round BlendMode.Clear strokes.\n// Changes: original procedural artwork replaces images; normalized coordinates survive resize;\n// union coverage on a fixed grid replaces overlapping area sums; no mutation in drawing;\n// reset/reveal buttons provide an alternative to touch gestures. Full license is exported.\n@Composable\nprivate fun StyleScratchmap(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    val strokes = remember { mutableStateListOf<ScratchmapStroke>() }\n    val coverage = remember { BooleanArray(32 * 32) }\n    var covered by remember { mutableIntStateOf(0) }\n    var revealed by remember { mutableStateOf(false) }\n    var generation by remember { mutableIntStateOf(0) }\n    val fontScale = LocalDensity.current.fontScale\n    val visibleStrokes = if (interactive) strokes else listOf(\n        ScratchmapStroke(Offset(.10f, .62f), Offset(.85f, .30f)),\n        ScratchmapStroke(Offset(.18f, .75f), Offset(.89f, .45f)),\n        ScratchmapStroke(Offset(.32f, .81f), Offset(.83f, .60f)),\n    )\n    fun scratch(from: Offset, to: Offset, width: Float, height: Float) {\n        if (revealed || strokes.size >= 4096) return\n        val a = Offset((from.x / width).coerceIn(0f, 1f), (from.y / height).coerceIn(0f, 1f))\n        val b = Offset((to.x / width).coerceIn(0f, 1f), (to.y / height).coerceIn(0f, 1f))\n        strokes.add(ScratchmapStroke(a, b))\n        covered = ScratchmapMarkCoverage(coverage, a.x, a.y, b.x, b.y, width, height)\n        if (covered >= coverage.size * .48f) revealed = true\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) {\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n            Text(p.caption, color = s.text, fontFamily = FontFamily.Monospace, fontSize = 9.sp, letterSpacing = 1.sp)\n            Text(\"NO. 018\", color = s.text.copy(alpha = .6f), fontFamily = FontFamily.Monospace, fontSize = 9.sp)\n        }\n        Text(p.headline, color = s.text, fontFamily = FontFamily.Serif, fontWeight = FontWeight.Bold,\n            fontSize = 30.sp, lineHeight = 38.sp)\n        Box(Modifier.fillMaxWidth().height(300.dp * fontScale.coerceAtLeast(1f)).clipToBounds()\n            .semantics {\n                contentDescription = \"星图刮印，拖动擦去表面，露出下面的星空海报\"\n                stateDescription = if (revealed) \"星图已全部显现\" else \"已擦除约 \${(covered * 100f / coverage.size).roundToInt()}%\"\n            }) {\n            Box(Modifier.fillMaxSize().background(s.panel).clearAndSetSemantics { }) {\n                Canvas(Modifier.fillMaxSize()) {\n                    repeat(76) { index ->\n                        val x = ((index * 73 + 17) % 257) / 257f * size.width\n                        val y = ((index * 113 + 29) % 293) / 293f * size.height\n                        drawCircle(s.bg.copy(alpha = .18f + (index % 4) * .12f), if (index % 9 == 0) 1.6.dp.toPx() else .7.dp.toPx(), Offset(x, y))\n                    }\n                    val hub = Offset(size.width * .68f, size.height * .47f)\n                    val radius = size.minDimension * .28f\n                    repeat(3) { ring -> drawCircle(s.extra.copy(alpha = .45f), radius * (1f + ring * .3f), hub, style = Stroke(.6.dp.toPx())) }\n                    var previous: Offset? = null\n                    repeat(6) { index ->\n                        val angle = index * 2.4f - .4f\n                        val star = hub + Offset(cos(angle), sin(angle)) * radius * (.7f + index % 2 * .3f)\n                        previous?.let { drawLine(s.extra, it, star, .8.dp.toPx()) }\n                        drawCircle(s.bg, 2.6.dp.toPx(), star)\n                        drawCircle(s.extra.copy(alpha = .2f), 6.dp.toPx(), star)\n                        previous = star\n                    }\n                }\n                Column(Modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.SpaceBetween) {\n                    Text(\"THE NIGHT\\nIS YOURS.\", color = s.bg, fontFamily = FontFamily.Serif,\n                        fontWeight = FontWeight.Bold, fontSize = 33.sp, lineHeight = 35.sp)\n                    Text(\"一小片未知，\\n值得亲手发现。\", color = s.bg, fontSize = 15.sp, lineHeight = 23.sp)\n                    Text(\"OBSERVATORY / 23:48 N\", color = s.extra, fontSize = 8.sp, fontFamily = FontFamily.Monospace)\n                }\n            }\n            if (!revealed) {\n                val touch = if (interactive) Modifier\n                    .pointerInput(generation) {\n                        detectDragGestures(onDragStart = { at -> scratch(at, at, size.width.toFloat(), size.height.toFloat()) }) { change, drag ->\n                            change.consume()\n                            scratch(change.position - drag, change.position, size.width.toFloat(), size.height.toFloat())\n                        }\n                    }\n                    .pointerInput(generation) {\n                        detectTapGestures { at -> scratch(at, at, size.width.toFloat(), size.height.toFloat()) }\n                    } else Modifier\n                Box(Modifier.fillMaxSize().then(touch).clearAndSetSemantics { }\n                    .graphicsLayer { compositingStrategy = CompositingStrategy.Offscreen }\n                    .drawWithContent {\n                        drawContent()\n                        visibleStrokes.forEach { stroke ->\n                            val from = Offset(stroke.from.x * size.width, stroke.from.y * size.height)\n                            val to = Offset(stroke.to.x * size.width, stroke.to.y * size.height)\n                            val brush = size.minDimension * .105f\n                            drawCircle(Color.Transparent, brush / 2, to, blendMode = BlendMode.Clear)\n                            drawLine(Color.Transparent, from, to, brush, StrokeCap.Round, blendMode = BlendMode.Clear)\n                        }\n                    }.background(s.primary)) {\n                    Canvas(Modifier.fillMaxSize()) {\n                        repeat(40) { row ->\n                            val y = row * size.height / 39\n                            drawLine(s.text.copy(alpha = .12f), Offset(0f, y), Offset(size.width, y - 26.dp.toPx()), .5.dp.toPx())\n                        }\n                        drawCircle(s.bg.copy(alpha = .5f), size.width * .28f, center, style = Stroke(1.dp.toPx()))\n                        drawCircle(s.text.copy(alpha = .25f), size.width * .23f, center, style = Stroke(.6.dp.toPx()))\n                    }\n                    Column(Modifier.align(Alignment.Center).padding(22.dp), horizontalAlignment = Alignment.CenterHorizontally) {\n                        Text(\"未\\n知\", color = s.text, fontSize = 55.sp, lineHeight = 60.sp, fontFamily = FontFamily.Serif, fontWeight = FontWeight.Bold)\n                        Text(\"SCRATCH TO DISCOVER\", Modifier.padding(top = 10.dp), color = s.text, fontSize = 8.sp, letterSpacing = 1.sp,\n                            fontFamily = FontFamily.Monospace)\n                    }\n                }\n            }\n        }\n        Text(if (revealed) \"这片星空，已经被你发现。\" else \"擦去表面 · 约一半面积后完整显现\", color = s.text.copy(alpha = .7f), fontSize = 11.sp, lineHeight = 17.sp)\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            Button(onClick = { revealed = true }, enabled = interactive && !revealed,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg,\n                    disabledContainerColor = s.text.copy(alpha = .1f), disabledContentColor = s.text.copy(alpha = .5f))) {\n                Text(p.action, fontSize = 12.sp)\n            }\n            TextButton(onClick = { strokes.clear(); coverage.fill(false); covered = 0; revealed = false; generation++ },\n                enabled = interactive, modifier = Modifier.weight(1f).heightIn(min = 48.dp),\n                colors = ButtonDefaults.textButtonColors(contentColor = s.text, disabledContentColor = s.text.copy(alpha = .5f))) {\n                Text(\"重新覆盖\", fontSize = 12.sp)\n            }\n        }\n    }\n}\n\nprivate data class ScratchmapStroke(val from: Offset, val to: Offset)\n\n/** Deduplicated grid coverage. Repeated scratches never count the same area twice. */\nprivate fun ScratchmapMarkCoverage(cells: BooleanArray, x1: Float, y1: Float, x2: Float, y2: Float, width: Float, height: Float): Int {\n    require(cells.size == 32 * 32)\n    val dx = (x2 - x1) * width\n    val dy = (y2 - y1) * height\n    val lengthSquared = dx * dx + dy * dy\n    val radius = min(width, height) * .105f / 2\n    for (row in 0 until 32) for (col in 0 until 32) {\n        val i = row * 32 + col\n        if (cells[i]) continue\n        val px = ((col + .5f) / 32 - x1) * width\n        val py = ((row + .5f) / 32 - y1) * height\n        val t = if (lengthSquared > 0f) ((px * dx + py * dy) / lengthSquared).coerceIn(0f, 1f) else 0f\n        val distanceSquared = (px - t * dx) * (px - t * dx) + (py - t * dy) * (py - t * dy)\n        if (distanceSquared <= radius * radius) cells[i] = true\n    }\n    return cells.count { it }\n}",
        "flowtext" to "// Adapted from chenglou/pretext, e699e27e7e4b48a50024fca545c6a12bc6ac975d:\n// pages/demos/dynamic-layout.ts (full-line-band layout/cursor) and\n// pages/demos/wrap-geometry.ts (carveTextLineSlots). MIT; see exported license.\n// Changes: analytic circle replaces polygon/logo hulls; both remaining slots consume one\n// continuous Chinese text stream. Android Paint measures text; no JS engine, fonts or logos.\n@Composable\nprivate fun StyleFlowtext(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    var discX by rememberSaveable { mutableFloatStateOf(.64f) }\n    var discY by rememberSaveable { mutableFloatStateOf(.42f) }\n    val density = LocalDensity.current\n    val prose = \"文字原本沿着直线前行，直到一个圆闯进纸面。它们轻轻让开，又在另一侧重新汇合。\" +\n        \"版式不再是一张固定的图，而是一场随手势发生的对话。拖动这枚珊瑚色圆片，观察每一行怎样寻找自己的空间。\" +\n        \"留白不是空缺，它让阅读有了停顿，也让形状拥有呼吸。没有预先画好的路线，每一次移动都会产生新的秩序。\"\n    val bodyPaint = remember(density.density, density.fontScale, s.ink) {\n        Paint(Paint.ANTI_ALIAS_FLAG).apply {\n            color = s.text.toArgb()\n            textSize = with(density) { 14.sp.toPx() }\n            typeface = Typeface.create(\"serif\", Typeface.NORMAL)\n        }\n    }\n    val discPaint = remember(density.density, s.ink) {\n        Paint(Paint.ANTI_ALIAS_FLAG).apply {\n            color = s.text.toArgb()\n            textSize = with(density) { 16.dp.toPx() }\n            textAlign = Paint.Align.CENTER\n            typeface = Typeface.create(\"sans-serif-condensed\", Typeface.BOLD)\n        }\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) {\n        Text(\"READ / REFLOW — 01\", color = s.text, fontFamily = FontFamily.Monospace,\n            fontSize = 10.sp, letterSpacing = 1.2.sp)\n        Text(p.headline, color = s.text, fontSize = 31.sp, lineHeight = 38.sp,\n            fontFamily = FontFamily.Serif, fontWeight = FontWeight.Bold)\n        HorizontalDivider(color = s.text.copy(alpha = .65f))\n        BoxWithConstraints(Modifier.fillMaxWidth()) {\n            val width = with(density) { maxWidth.toPx() }\n            val radius = min(width * .225f, with(density) { 65.dp.toPx() })\n            val gap = with(density) { 9.dp.toPx() }\n            val lineHeight = max(with(density) { 23.sp.toPx() }, bodyPaint.fontMetrics.bottom - bodyPaint.fontMetrics.top)\n            // Reserve enough rows for the entire paragraph, including the worst obstruction.\n            val plainRows = ceil(bodyPaint.measureText(prose) / width.coerceAtLeast(1f))\n            val height = max(with(density) { 276.dp.toPx() }, (plainRows + 3) * lineHeight + radius * 2 + gap * 2)\n            val x = (discX * width).coerceIn(radius, (width - radius).coerceAtLeast(radius))\n            val y = (discY * height).coerceIn(radius, (height - radius).coerceAtLeast(radius))\n            val circle = Offset(x, y)\n            val lines = remember(width, height, circle, radius, gap, lineHeight, bodyPaint) {\n                FlowtextLines(prose, bodyPaint, width, height, lineHeight, circle, radius + gap)\n            }\n            Box(Modifier.fillMaxWidth().height(with(density) { height.toDp() })) {\n                Canvas(Modifier.fillMaxSize().semantics { contentDescription = prose }) {\n                    lines.forEach { line ->\n                        drawContext.canvas.nativeCanvas.drawText(line.text, line.x,\n                            line.top - bodyPaint.fontMetrics.top, bodyPaint)\n                    }\n                    drawCircle(s.primary.copy(alpha = .14f), radius, circle + Offset(3.dp.toPx(), 5.dp.toPx()))\n                    drawCircle(s.primary, radius, circle)\n                    drawCircle(s.text.copy(alpha = .22f), radius - 6.dp.toPx(), circle, style = Stroke(.8.dp.toPx()))\n                    drawContext.canvas.nativeCanvas.drawText(\"MOVE ME\", x, y + 5.dp.toPx(), discPaint)\n                    val arrowY = y + radius * .5f\n                    drawLine(s.text, Offset(x - radius * .28f, arrowY), Offset(x + radius * .28f, arrowY), 1.dp.toPx())\n                    drawLine(s.text, Offset(x + radius * .17f, arrowY - 4.dp.toPx()), Offset(x + radius * .28f, arrowY), 1.dp.toPx())\n                    drawLine(s.text, Offset(x - radius * .17f, arrowY + 4.dp.toPx()), Offset(x - radius * .28f, arrowY), 1.dp.toPx())\n                }\n                if (interactive) {\n                    // Only the disc captures drag; swiping the paragraph still scrolls the detail sheet.\n                    Box(Modifier.offset { IntOffset((x - radius).roundToInt(), (y - radius).roundToInt()) }\n                        .size(with(density) { (radius * 2).toDp() })\n                        .pointerInput(width, height, radius) {\n                            detectDragGestures { change, delta ->\n                                change.consume()\n                                discX = ((discX * width + delta.x).coerceIn(radius, width - radius)) / width\n                                discY = ((discY * height + delta.y).coerceIn(radius, height - radius)) / height\n                            }\n                        }.semantics {\n                            contentDescription = \"可拖动的圆形排版留白，也可以使用下方位置按钮\"\n                            stateDescription = \"横向 \${(discX * 100).roundToInt()}%，纵向 \${(discY * 100).roundToInt()}%\"\n                        })\n                }\n            }\n        }\n        HorizontalDivider(color = s.text.copy(alpha = .18f))\n        Text(\"移动形状，让文字自己找到位置。\", color = s.text.copy(alpha = .68f), fontSize = 11.sp, lineHeight = 17.sp)\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(4.dp)) {\n            listOf(\"左侧\", \"中央\", \"右侧\").forEachIndexed { index, label ->\n                TextButton(onClick = { discX = .25f + index * .25f; discY = .42f }, enabled = interactive,\n                    modifier = Modifier.weight(1f).heightIn(min = 48.dp)\n                        .semantics { contentDescription = \"把圆片移到\$label\" },\n                    colors = ButtonDefaults.textButtonColors(contentColor = s.text, disabledContentColor = s.text.copy(alpha = .55f))) {\n                    Text(label, fontSize = 12.sp, textAlign = TextAlign.Center)\n                }\n            }\n        }\n    }\n}\n\nprivate data class FlowtextRun(val text: String, val x: Float, val top: Float)\n\nprivate fun FlowtextSlots(left: Float, right: Float, blockedLeft: Float, blockedRight: Float, minWidth: Float): List<Pair<Float, Float>> {\n    // Specialized carveTextLineSlots: one analytic circle contributes a single blocked interval.\n    if (blockedRight <= left || blockedLeft >= right) return listOf(left to right)\n    val slots = mutableListOf<Pair<Float, Float>>()\n    if (blockedLeft > left) slots += left to min(blockedLeft, right)\n    if (blockedRight < right) slots += max(blockedRight, left) to right\n    return slots.filter { it.second - it.first >= minWidth }\n}\n\nprivate fun FlowtextLines(text: String, paint: Paint, width: Float, height: Float,\n    lineHeight: Float, circle: Offset, radius: Float): List<FlowtextRun> {\n    val runs = mutableListOf<FlowtextRun>()\n    var cursor = 0\n    var top = 0f\n    while (cursor < text.length && top + lineHeight <= height) {\n        // Use the largest chord intersecting the entire text band, avoiding glyph/disc collisions.\n        val closestY = circle.y.coerceIn(top, top + lineHeight)\n        val dy = closestY - circle.y\n        val halfChord = if (kotlin.math.abs(dy) < radius) sqrt(radius * radius - dy * dy) else 0f\n        val slots = if (halfChord == 0f) listOf(0f to width)\n            else FlowtextSlots(0f, width, circle.x - halfChord, circle.x + halfChord, paint.textSize)\n        for ((left, right) in slots) {\n            if (cursor == text.length) break\n            val count = paint.breakText(text, cursor, text.length, true, right - left, null)\n            if (count <= 0) continue\n            runs += FlowtextRun(text.substring(cursor, cursor + count), left, top)\n            cursor += count\n        }\n        top += lineHeight\n    }\n    return runs\n}",
        "arcchart" to "// Adapted from developerchunk/Custom-Pie-Chart-Jetpack-Compose,\n// commit 2d14dfb1ccc98eded6412b9f5dbf83f59cdeda8b, PieChart.kt. MIT; see exported license.\n// Changes: fixed-size orbital canvas, selectable sectors, original labels, guarded normalization,\n// cyclic palette and draw-local angle accumulation. No upstream Activity, theme or assets copied.\n@Composable\nprivate fun StyleArcchart(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    val weights = listOf(45f, 32f, 23f)\n    val fractions = remember { ArcchartFractions(weights) }\n    val colors = listOf(s.primary, s.extra, s.text)\n    val labels = p.items\n    var selected by rememberSaveable { mutableIntStateOf(0) }\n    var replay by remember { mutableIntStateOf(0) }\n    val reveal = remember { Animatable(if (interactive) 0f else 1f) }\n    LaunchedEffect(interactive, replay) {\n        if (interactive) {\n            reveal.snapTo(0f)\n            reveal.animateTo(1f, tween(1000, easing = FastOutSlowInEasing))\n        } else reveal.snapTo(1f)\n    }\n    val emphasis = weights.indices.map { index ->\n        animateFloatAsState(if (selected == index) 1f else 0f, tween(260), label = \"arc-emphasis-\$index\").value\n    }\n    val density = LocalDensity.current\n    val labelPaint = remember(density.density, s.ink) {\n        Paint(Paint.ANTI_ALIAS_FLAG).apply {\n            color = s.text.toArgb()\n            typeface = Typeface.create(\"casual\", Typeface.NORMAL)\n            textSize = with(density) { 12.dp.toPx() }\n            textAlign = Paint.Align.CENTER\n        }\n    }\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Text(\"A DAY, IN ORBIT / 24H\", fontFamily = FontFamily.Monospace, color = s.text,\n            fontSize = 10.sp, letterSpacing = .9.sp)\n        Text(p.headline, color = s.text, fontSize = 30.sp, lineHeight = 38.sp,\n            fontWeight = FontWeight.Bold, fontFamily = FontFamily.Serif)\n        BoxWithConstraints(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {\n            val side = minOf(maxWidth, 330.dp)\n            Box(Modifier.size(side), contentAlignment = Alignment.Center) {\n                Canvas(Modifier.fillMaxSize()\n                    .then(if (interactive) Modifier.pointerInput(fractions) {\n                        detectTapGestures { position ->\n                            val dx = position.x - size.width / 2f\n                            val dy = position.y - size.height / 2f\n                            val radius = min(size.width, size.height).toFloat()\n                            val distance = sqrt(dx * dx + dy * dy)\n                            if (distance in radius * .24f..radius * .43f) {\n                                val angle = ((atan2(dy, dx) * 180f / PI.toFloat()) + 450f) % 360f\n                                var end = 0f\n                                for (index in fractions.indices) {\n                                    end += fractions[index] * 360f\n                                    if (angle <= end) { selected = index; break }\n                                }\n                            }\n                        }\n                    } else Modifier)\n                    .semantics { contentDescription = \"时间分配圆环图。\${labels.mapIndexed { i, name -> \"\$name \${(fractions[i] * 100).roundToInt()}%\" }.joinToString(\"，\")}。下方列表可选择扇区\" }) {\n                    val r = size.minDimension * .33f\n                    repeat(60) { index ->\n                        val angle = index * PI / 30 - PI / 2\n                        val direction = Offset(cos(angle).toFloat(), sin(angle).toFloat())\n                        val tick = if (index % 5 == 0) .018f else .007f\n                        drawLine(s.text.copy(alpha = if (index % 5 == 0) .4f else .16f),\n                            center + direction * size.minDimension * (.44f - tick),\n                            center + direction * size.minDimension * .44f, 1.dp.toPx())\n                    }\n                    drawCircle(s.text.copy(alpha = .12f), size.minDimension * .205f, style = Stroke(1.dp.toPx()))\n                    var start = -90f // Reset on every draw; no shared mutable angle across animation frames.\n                    fractions.forEachIndexed { index, fraction ->\n                        val sweep = fraction * 360f\n                        val mid = (start + sweep / 2) * PI / 180\n                        val direction = Offset(cos(mid).toFloat(), sin(mid).toFloat())\n                        val lift = direction * (6.dp.toPx() * emphasis[index])\n                        val arcCenter = center + lift\n                        val stroke = size.minDimension * (.075f + emphasis[index] * .035f)\n                        drawArc(colors[index % colors.size].copy(alpha = .35f + emphasis[index] * .65f),\n                            start + 3f, max(0f, sweep - 6f) * reveal.value, false,\n                            arcCenter - Offset(r, r), Size(r * 2, r * 2), style = Stroke(stroke, cap = StrokeCap.Butt))\n                        val label = center + direction * size.minDimension * .48f\n                        drawContext.canvas.nativeCanvas.drawText(\"0\${index + 1}\", label.x,\n                            label.y - (labelPaint.ascent() + labelPaint.descent()) / 2, labelPaint)\n                        start += sweep\n                    }\n                }\n                Column(horizontalAlignment = Alignment.CenterHorizontally,\n                    modifier = Modifier.width(side * .4f), verticalArrangement = Arrangement.spacedBy(2.dp)) {\n                    Text(\"\${(fractions[selected] * 100).roundToInt()}%\", color = s.text,\n                        fontSize = if (density.fontScale > 1.3f) 26.sp else 38.sp,\n                        fontFamily = FontFamily.Serif, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)\n                    Text(labels[selected], color = s.text.copy(alpha = .65f), fontSize = 11.sp,\n                        textAlign = TextAlign.Center)\n                }\n            }\n        }\n        Text(\"每一份时间，都有自己的轨道。\", color = s.text.copy(alpha = .65f), fontSize = 11.sp, lineHeight = 18.sp)\n        Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {\n            labels.forEachIndexed { index, label ->\n                Row(Modifier.fillMaxWidth()\n                    .background(if (selected == index) s.panel else Color.Transparent, RoundedCornerShape(12.dp))\n                    .selectable(selected == index, enabled = interactive, role = Role.RadioButton, onClick = { selected = index })\n                    .padding(horizontal = 12.dp, vertical = 11.dp),\n                    verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n                    Box(Modifier.size(9.dp).background(colors[index % colors.size], RoundedCornerShape(2.dp)))\n                    Text(\"0\${index + 1}\", color = s.text.copy(alpha = .5f), fontFamily = FontFamily.Monospace, fontSize = 10.sp)\n                    Text(label, color = s.text, fontSize = 13.sp, modifier = Modifier.weight(1f))\n                    Text(\"\${(fractions[index] * 100).roundToInt()}%\", color = s.text,\n                        fontFamily = FontFamily.Monospace, fontSize = 12.sp)\n                }\n            }\n        }\n        TextButton(onClick = { replay++ }, enabled = interactive, modifier = Modifier.fillMaxWidth().heightIn(min = 48.dp),\n            colors = ButtonDefaults.textButtonColors(contentColor = s.text, disabledContentColor = s.text.copy(alpha = .5f))) {\n            Text(p.action, fontSize = 12.sp, textAlign = TextAlign.Center)\n        }\n    }\n}\n\nprivate fun ArcchartFractions(values: List<Float>): List<Float> {\n    val positive = values.map { if (it.isFinite()) max(0f, it) else 0f }\n    val total = positive.sum()\n    return if (total > 0f) positive.map { it / total } else positive.map { 0f }\n}",
        "typesort" to "/**\n * Minimal port of William Candillon's Chrome Drag-to-Sort, MIT, copyright 2019.\n * Video: https://www.youtube.com/watch?v=-39OEXk_mWc\n * https://github.com/wcandillon/can-it-be-done-in-react-native/blob/72678212d4041f124e1585cdf6360f36737daa5f/season4/src/Chrome/Config.tsx\n * https://github.com/wcandillon/can-it-be-done-in-react-native/blob/72678212d4041f124e1585cdf6360f36737daa5f/season4/src/Chrome/Item.tsx\n * Retains rounded coordinate-to-order mapping, pairwise slot swaps and lifted\n * active-item layering. Native finite springs replace React timing; long press\n * protects surrounding vertical scrolling. Adds bounded axes, original type\n * specimens, button-based ordering and a motionless thumbnail. No tab images,\n * browser UI, autoscrolling infrastructure or JavaScript dependencies copied.\n * Full MIT notice: tools/creative/licenses/candillon-drag-sort.txt.\n */\n@Composable\nprivate fun StyleTypesort(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    val items = p.items.ifEmpty { listOf(p.headline) }.take(12)\n    var order by remember(items) { mutableStateOf(items.indices.toList()) }\n    var selected by remember(items) { mutableIntStateOf(0) }\n    var activeId by remember(items) { mutableStateOf<Int?>(null) }\n    var dragPosition by remember { mutableStateOf(Offset.Zero) }\n    var releaseJob by remember { mutableStateOf<Job?>(null) }\n    val scope = rememberCoroutineScope()\n    val density = LocalDensity.current\n    val fontScale = density.fontScale.coerceAtLeast(1f)\n    val palette = listOf(s.primary, s.extra, s.panel, s.text)\n    val currentSlot = order.indexOf(selected)\n    val swapSelected: (Int) -> Unit = { direction ->\n        val destination = (order.indexOf(selected) + direction).coerceIn(order.indices)\n        order = TypesortSwapOrder(order, selected, destination)\n    }\n\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Text(p.caption, color = s.text.copy(alpha = .7f), fontSize = 9.sp,\n            fontFamily = FontFamily.Monospace, letterSpacing = 1.sp)\n        Text(p.headline, Modifier.padding(top = 12.dp), color = s.text, fontSize = 27.sp,\n            lineHeight = 35.sp, fontWeight = FontWeight.Black, fontFamily = s.font)\n        Text(\"长按一块字，拖到另一个位置\", Modifier.padding(top = 8.dp, bottom = 16.dp),\n            color = s.text.copy(alpha = .65f), fontSize = 11.sp, lineHeight = 17.sp)\n\n        BoxWithConstraints(Modifier.fillMaxWidth()) {\n            val columns = if (items.size == 1) 1 else 2\n            val rows = (items.size + columns - 1) / columns\n            val cellWidth = maxWidth / columns\n            val cellHeight = 146.dp * fontScale\n            val cellWidthPx = with(density) { cellWidth.toPx() }\n            val cellHeightPx = with(density) { cellHeight.toPx() }\n            val glyphSize = minOf((cellWidth.value * .40f).coerceIn(28f, 56f),\n                (cellWidth.value - 36f) / fontScale).coerceAtLeast(16f)\n            val positions = remember(items, cellWidthPx, cellHeightPx) {\n                List(items.size) { id ->\n                    val slot = order.indexOf(id)\n                    Animatable(Offset((slot % columns) * cellWidthPx, (slot / columns) * cellHeightPx), Offset.VectorConverter)\n                }\n            }\n            val release: () -> Unit = {\n                val id = activeId\n                if (id != null) {\n                    releaseJob?.cancel()\n                    val droppedAt = dragPosition\n                    releaseJob = scope.launch {\n                        positions[id].snapTo(droppedAt)\n                        if (activeId == id) activeId = null\n                    }\n                }\n            }\n            val latestRelease by rememberUpdatedState(release)\n            val gesture = if (interactive) Modifier.pointerInput(items, cellWidthPx, cellHeightPx) {\n                try {\n                    detectDragGesturesAfterLongPress(\n                        onDragStart = { at ->\n                            releaseJob?.cancel()\n                            val column = floor(at.x / cellWidthPx).toInt().coerceIn(0, columns - 1)\n                            val row = floor(at.y / cellHeightPx).toInt().coerceIn(0, rows - 1)\n                            val slot = row * columns + column\n                            if (slot < order.size) {\n                                val id = order[slot]\n                                selected = id\n                                dragPosition = positions[id].value\n                                activeId = id\n                            }\n                        },\n                        onDrag = { change, amount ->\n                            val id = activeId\n                            if (id != null) {\n                                change.consume()\n                                dragPosition = Offset(\n                                    (dragPosition.x + amount.x).coerceIn(0f, (columns - 1) * cellWidthPx),\n                                    (dragPosition.y + amount.y).coerceIn(0f, (rows - 1) * cellHeightPx),\n                                )\n                                val destination = TypesortTargetOrder(dragPosition.x, dragPosition.y,\n                                    cellWidthPx, cellHeightPx, items.size)\n                                order = TypesortSwapOrder(order, id, destination)\n                            }\n                        },\n                        onDragEnd = { latestRelease() },\n                        onDragCancel = { latestRelease() },\n                    )\n                } finally {\n                    // A size change or leaving composition must not leave a held tile.\n                    activeId = null\n                }\n            } else Modifier\n\n            Box(Modifier.fillMaxWidth().height(cellHeight * rows).background(s.text.copy(alpha = .13f)).then(gesture)) {\n                items.forEachIndexed { id, label ->\n                    val slot = order.indexOf(id)\n                    val target = Offset((slot % columns) * cellWidthPx, (slot / columns) * cellHeightPx)\n                    val held = activeId == id\n                    val position = positions[id]\n                    LaunchedEffect(target, held, interactive) {\n                        if (interactive && !held) position.animateTo(target,\n                            spring(dampingRatio = .78f, stiffness = 410f))\n                    }\n                    val color = palette[id % palette.size]\n                    val light = .2126f * color.red + .7152f * color.green + .0722f * color.blue > .58f\n                    val ink = if (light) Color(0xFF242323) else Color(0xFFFFFAED)\n                    val tileSelection = if (interactive) Modifier.selectable(selected == id,\n                        role = Role.RadioButton) { selected = id }.semantics {\n                        contentDescription = \"字块 \$label\"\n                        stateDescription = \"第 \${slot + 1} 位，共 \${items.size} 位。长按拖动，或选择后使用前移、后移按钮\"\n                    } else Modifier\n                    Box(Modifier.offset {\n                        val at = if (!interactive) target else if (held) dragPosition else position.value\n                        IntOffset(at.x.roundToInt(), at.y.roundToInt())\n                    }.size(cellWidth, cellHeight).zIndex(if (held) 2f else 0f)\n                        .padding(3.dp).graphicsLayer {\n                            scaleX = if (held) 1.035f else 1f\n                            scaleY = scaleX\n                            rotationZ = if (held) -2f else 0f\n                            shadowElevation = if (held) 12.dp.toPx() else 0f\n                        }.background(color)\n                        .then(if (selected == id) Modifier.border(2.dp, ink) else Modifier)\n                        .then(tileSelection)) {\n                        Canvas(Modifier.fillMaxSize()) {\n                            val inset = 9.dp.toPx()\n                            val arm = 4.dp.toPx()\n                            listOf(Offset(inset, inset), Offset(size.width - inset, size.height - inset)).forEach { mark ->\n                                drawLine(ink.copy(alpha = .6f), mark - Offset(arm, 0f), mark + Offset(arm, 0f), 1.dp.toPx())\n                                drawLine(ink.copy(alpha = .6f), mark - Offset(0f, arm), mark + Offset(0f, arm), 1.dp.toPx())\n                            }\n                            drawLine(ink.copy(alpha = .2f), Offset(inset, size.height - 30.dp.toPx()),\n                                Offset(size.width - inset, size.height - 30.dp.toPx()), .7.dp.toPx())\n                        }\n                        Column(Modifier.fillMaxSize().padding(horizontal = 13.dp, vertical = 12.dp)) {\n                            Text(\"TYPE \${(id + 1).toString().padStart(2, '0')}\", Modifier.padding(start = 8.dp),\n                                color = ink.copy(alpha = .7f), fontSize = 8.sp, lineHeight = 11.sp,\n                                fontFamily = FontFamily.Monospace, maxLines = 1)\n                            Box(Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {\n                                Text(label, color = ink, fontSize = glyphSize.sp, lineHeight = (glyphSize * 1.1f).sp,\n                                    fontFamily = if (id % 2 == 0) FontFamily.Serif else FontFamily.SansSerif,\n                                    fontWeight = FontWeight.Black, textAlign = TextAlign.Center,\n                                    maxLines = 2, overflow = TextOverflow.Ellipsis)\n                            }\n                            Text(\"\${(slot + 1).toString().padStart(2, '0')}  /  \${if (held) \"DRAG\" else \"MOVE\"}\",\n                                color = ink, fontSize = 9.sp, lineHeight = 12.sp, fontFamily = FontFamily.Monospace)\n                        }\n                    }\n                }\n            }\n        }\n        Text(order.joinToString(\"  \") { items[it] }, color = s.text,\n            fontSize = 18.sp, lineHeight = 27.sp, fontWeight = FontWeight.Bold,\n            modifier = Modifier.padding(top = 15.dp).semantics { contentDescription = \"当前顺序：\${order.joinToString(\"，\") { items[it] }}\" })\n        Text(\"已选择「\${items[selected]}」 · 第 \${currentSlot + 1} 位\", Modifier.padding(top = 4.dp, bottom = 13.dp),\n            color = s.text.copy(alpha = .65f), fontSize = 11.sp, lineHeight = 17.sp)\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            Button(onClick = { swapSelected(-1) }, enabled = interactive && activeId == null && currentSlot > 0,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp), shape = RoundedCornerShape(0.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg)) {\n                Text(\"← 前移\", fontSize = 12.sp)\n            }\n            Button(onClick = { swapSelected(1) }, enabled = interactive && activeId == null && currentSlot < items.lastIndex,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp), shape = RoundedCornerShape(0.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.text, contentColor = s.bg)) {\n                Text(\"后移 →\", fontSize = 12.sp)\n            }\n        }\n        TextButton(onClick = { order = items.indices.toList() }, enabled = interactive && activeId == null,\n            modifier = Modifier.fillMaxWidth().heightIn(min = 48.dp),\n            colors = ButtonDefaults.textButtonColors(contentColor = s.text)) {\n            Text(p.action, fontSize = 12.sp)\n        }\n    }\n}\n\n/** Upstream getOrder, with separately bounded rows/columns and rectangular cells. */\nprivate fun TypesortTargetOrder(x: Float, y: Float, width: Float, height: Float, count: Int): Int {\n    if (count <= 1) return 0\n    val column = (x / width.coerceAtLeast(1f)).roundToInt().coerceIn(0, 1)\n    val row = (y / height.coerceAtLeast(1f)).roundToInt().coerceIn(0, (count - 1) / 2)\n    return (row * 2 + column).coerceAtMost(count - 1)\n}\n\n/** Exchange occupied slots without duplicating or dropping any item identity. */\nprivate fun TypesortSwapOrder(order: List<Int>, id: Int, destination: Int): List<Int> {\n    val from = order.indexOf(id)\n    if (from < 0 || destination !in order.indices || from == destination) return order\n    return order.toMutableList().apply {\n        this[from] = this[destination]\n        this[destination] = id\n    }\n}",
        "depthwheel" to "// Minimal port of William Candillon's iOS-Style Picker (MIT, copyright 2019).\n// Video: https://www.youtube.com/watch?v=PVSjPswRn0U\n// https://github.com/wcandillon/can-it-be-done-in-react-native/blob/72678212d4041f124e1585cdf6360f36737daa5f/the-10-min/src/Picker/Picker.tsx\n// https://github.com/wcandillon/can-it-be-done-in-react-native/blob/72678212d4041f124e1585cdf6360f36737daa5f/the-10-min/src/Picker/AnimationHelpers.tsx\n// Extracted: asin item rotation, cylindrical depth and equally spaced snap points.\n// Changes: Compose graphics layers replace the masked React tree; a bounded\n// velocity projection + spring replace Reanimated timing; new mechanical drum\n// artwork and native previous/next controls. No upstream fonts or images copied.\n// Full MIT notice: tools/creative/licenses/candillon-picker.txt.\n@Composable\nprivate fun StyleDepthwheel(s: CreativeStyleSpec, p: CreativePattern, interactive: Boolean) {\n    val items = p.items.ifEmpty { listOf(p.headline) }\n    val initial = minOf(3, items.lastIndex)\n    var selected by rememberSaveable { mutableIntStateOf(initial) }\n    val position = remember { Animatable(selected.toFloat()) }\n    var dragging by remember { mutableStateOf(false) }\n    var dragPosition by remember { mutableFloatStateOf(selected.toFloat()) }\n    var snapJob by remember { mutableStateOf<Job?>(null) }\n    val scope = rememberCoroutineScope()\n    val velocity = remember { VelocityTracker() }\n    val density = LocalDensity.current\n    val rowHeight = 58.dp * density.fontScale.coerceAtLeast(1f)\n    val rowPx = with(density) { rowHeight.toPx() }\n    val visiblePosition = if (!interactive) initial.toFloat() else if (dragging) dragPosition else position.value\n    val activeIndex = visiblePosition.roundToInt().coerceIn(items.indices)\n\n    val settle: (Float) -> Unit = { target ->\n        if (interactive) {\n            val from = if (dragging) dragPosition else position.value\n            val destination = target.roundToInt().coerceIn(items.indices)\n            snapJob?.cancel()\n            snapJob = scope.launch {\n                position.snapTo(from)\n                dragging = false\n                selected = destination\n                position.animateTo(destination.toFloat(), spring(dampingRatio = .83f, stiffness = 210f))\n            }\n        }\n    }\n    val latestSettle by rememberUpdatedState(settle)\n    val gesture = if (interactive) Modifier.pointerInput(rowPx, items.size) {\n        detectVerticalDragGestures(\n            onDragStart = {\n                snapJob?.cancel()\n                dragPosition = position.value\n                dragging = true\n                velocity.resetTracking()\n            },\n            onVerticalDrag = { change, amount ->\n                change.consume()\n                velocity.addPosition(change.uptimeMillis, change.position)\n                dragPosition = (dragPosition - amount / rowPx).coerceIn(0f, items.lastIndex.toFloat())\n            },\n            onDragEnd = {\n                // Predict a short travel, capped at two rows, then snap to a real item.\n                val projectedTravel = (-velocity.calculateVelocity().y * .16f / rowPx).coerceIn(-2f, 2f)\n                latestSettle(dragPosition + projectedTravel)\n            },\n            onDragCancel = { latestSettle(dragPosition) },\n        )\n    } else Modifier\n\n    Column(Modifier.fillMaxWidth().background(s.bg).padding(18.dp)) {\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = Alignment.CenterVertically) {\n            Text(p.caption, Modifier.weight(1f), color = s.extra, fontFamily = FontFamily.Monospace,\n                fontSize = 10.sp, letterSpacing = 1.sp)\n            Text(p.value, Modifier.padding(start = 12.dp), color = s.text.copy(alpha = .6f),\n                fontFamily = FontFamily.Monospace, fontSize = 9.sp)\n        }\n        Text(p.headline, Modifier.padding(top = 15.dp, bottom = 5.dp), color = s.text,\n            fontSize = 25.sp, lineHeight = 32.sp, fontFamily = s.font, fontWeight = FontWeight.Bold)\n        Text(\"向上或向下拨动，让节奏落在刻度上\", color = s.text.copy(alpha = .64f),\n            fontSize = 11.sp, lineHeight = 17.sp)\n        Spacer(Modifier.height(20.dp))\n\n        BoxWithConstraints(Modifier.fillMaxWidth()) {\n            val wheelWidth = maxWidth\n            val itemFontSize = (wheelWidth.value * .104f).coerceIn(23f, 34f).sp\n            val drumShape = CutCornerShape(topStart = 17.dp, bottomEnd = 17.dp)\n            Box(Modifier.fillMaxWidth().height(rowHeight * 5f).clip(drumShape)\n                .background(s.panel).border(1.dp, s.text.copy(alpha = .16f), drumShape)\n                .then(gesture)\n                .semantics {\n                    contentDescription = \"立体滚筒选择器\"\n                    stateDescription = \"\${items[activeIndex]}，第 \${activeIndex + 1} 档，共 \${items.size} 档\"\n                }) {\n                Canvas(Modifier.fillMaxSize().clearAndSetSemantics { }) {\n                    val inset = size.width * .08f\n                    val bandTop = (size.height - rowPx) / 2\n                    drawRect(Brush.horizontalGradient(listOf(s.bg, s.panel, s.panel, s.bg)))\n                    // Curved side seams and compressed ticks give the drum a visible volume.\n                    listOf(inset, size.width - inset).forEach { x ->\n                        val towardCenter = if (x < center.x) size.width * .10f else -size.width * .10f\n                        val seam = Path().apply {\n                            moveTo(x, -rowPx)\n                            cubicTo(x + towardCenter, rowPx, x + towardCenter, size.height - rowPx, x, size.height + rowPx)\n                        }\n                        drawPath(seam, s.extra.copy(alpha = .42f), style = Stroke(1.dp.toPx()))\n                    }\n                    repeat(29) { tick ->\n                        val relative = (tick - 14) / 14f\n                        val y = center.y + relative * size.height * .48f\n                        val length = if (tick % 4 == 2) 9.dp.toPx() else 4.dp.toPx()\n                        val fade = 1f - abs(relative) * .76f\n                        drawLine(s.text.copy(alpha = .42f * fade), Offset(inset * .36f, y),\n                            Offset(inset * .36f + length, y), 1.dp.toPx())\n                        drawLine(s.text.copy(alpha = .42f * fade), Offset(size.width - inset * .36f, y),\n                            Offset(size.width - inset * .36f - length, y), 1.dp.toPx())\n                    }\n                    drawRoundRect(s.primary, Offset(8.dp.toPx(), bandTop), Size(size.width - 16.dp.toPx(), rowPx),\n                        CornerRadius(3.dp.toPx()))\n                    val arrow = Path().apply {\n                        moveTo(15.dp.toPx(), center.y - 4.dp.toPx())\n                        lineTo(20.dp.toPx(), center.y)\n                        lineTo(15.dp.toPx(), center.y + 4.dp.toPx())\n                    }\n                    drawPath(arrow, s.bg, style = Stroke(2.dp.toPx(), cap = StrokeCap.Round))\n                }\n                items.forEachIndexed { index, label ->\n                    val distance = index - visiblePosition\n                    if (abs(distance) < 2.75f) {\n                        val projection = StyleDepthWheelProjection(distance, rowPx)\n                        Row(\n                            Modifier.align(Alignment.Center).fillMaxWidth(.78f).height(rowHeight)\n                                .graphicsLayer {\n                                    translationY = distance * rowPx\n                                    rotationX = projection.first\n                                    scaleX = projection.second\n                                    scaleY = projection.second\n                                    alpha = projection.third\n                                    cameraDistance = 600.dp.toPx()\n                                }\n                                .clearAndSetSemantics { },\n                            verticalAlignment = Alignment.CenterVertically,\n                            horizontalArrangement = Arrangement.spacedBy(12.dp),\n                        ) {\n                            val ink = if (index == activeIndex) s.bg else s.text\n                            Text((index + 1).toString().padStart(2, '0'), color = ink.copy(alpha = .7f),\n                                fontSize = 11.sp, fontFamily = FontFamily.Monospace,\n                                modifier = Modifier.width(27.dp))\n                            Text(label, color = ink, fontSize = itemFontSize, fontWeight = FontWeight.Black,\n                                fontFamily = s.font, modifier = Modifier.weight(1f), maxLines = 1)\n                        }\n                    }\n                }\n                Canvas(Modifier.fillMaxSize().clearAndSetSemantics { }) {\n                    // Stationary light falloff, not a continuously running shader/animation.\n                    drawRect(Brush.verticalGradient(0f to s.bg, .22f to Color.Transparent,\n                        .78f to Color.Transparent, 1f to s.bg))\n                    drawCircle(s.extra, 2.dp.toPx(), Offset(size.width - 18.dp.toPx(), 18.dp.toPx()))\n                }\n            }\n        }\n        Row(Modifier.fillMaxWidth().padding(top = 14.dp, bottom = 14.dp),\n            horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {\n            Column(Modifier.weight(1f)) {\n                Text(\"当前节奏\", color = s.text.copy(alpha = .62f), fontSize = 10.sp)\n                Text(items[activeIndex], color = s.primary, fontSize = 18.sp, fontWeight = FontWeight.Bold,\n                    modifier = Modifier.padding(top = 3.dp))\n            }\n            Text(\"\${(activeIndex + 1).toString().padStart(2, '0')} / \${items.size.toString().padStart(2, '0')}\",\n                color = s.extra, fontSize = 12.sp, fontFamily = FontFamily.Monospace)\n        }\n        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n            Button(onClick = { settle((activeIndex - 1).toFloat()) },\n                enabled = interactive && activeIndex > 0,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp),\n                shape = CutCornerShape(8.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.panel, contentColor = s.text,\n                    disabledContainerColor = s.panel, disabledContentColor = s.text.copy(alpha = .35f)),\n            ) { Text(\"↑  上一档\", fontSize = 12.sp) }\n            Button(onClick = { settle((activeIndex + 1).toFloat()) },\n                enabled = interactive && activeIndex < items.lastIndex,\n                modifier = Modifier.weight(1f).heightIn(min = 48.dp),\n                shape = CutCornerShape(8.dp),\n                colors = ButtonDefaults.buttonColors(containerColor = s.primary, contentColor = s.bg,\n                    disabledContainerColor = s.primary, disabledContentColor = s.bg.copy(alpha = .4f)),\n            ) { Text(\"\${p.action}  ↓\", fontSize = 12.sp, fontWeight = FontWeight.Bold) }\n        }\n    }\n}\n\n/** The upstream cylindrical projection, expressed as rotation, depth scale and visibility. */\nprivate fun StyleDepthWheelProjection(distance: Float, rowHeight: Float): Triple<Float, Float, Float> {\n    val relativeRadius = 2.5f\n    val normalized = (-distance / relativeRadius).coerceIn(-1f, 1f)\n    val angle = asin(normalized)\n    val radius = relativeRadius * rowHeight\n    val depth = radius * cos(angle) - radius\n    val perspective = rowHeight * (600f / 58f)\n    return Triple(\n        angle * (180f / PI.toFloat()),\n        perspective / (perspective - depth),\n        (1f - abs(normalized) * .76f).coerceIn(.16f, 1f),\n    )\n}",
    )
    private val names = mapOf(
        "archive" to "StyleArchive",
        "flora" to "StyleFlora",
        "transit" to "StyleTransit",
        "focus" to "StyleFocus",
        "orbit" to "StyleOrbit",
        "spectrum" to "StyleSpectrum",
        "terrain" to "StyleTerrain",
        "kinetic" to "StyleKinetic",
