        "foiltilt" to "StyleFoiltilt",
        "depthstack" to "StyleDepthstack",
        "flapcounter" to "StyleFlapcounter",
        "liquidswipe" to "StyleLiquidswipe",
        "elasticnav" to "StyleElasticnav",
