        "radialtool" to listOf("StyleRadialtool"),
        "fielddots" to listOf("StyleFielddots", "FielddotsControls", "FielddotsParticle", "FielddotsInitial", "FielddotsStep"),
        "morphstamp" to listOf("StyleMorphstamp", "MorphstampChoice", "MorphstampRings", "MorphstampPointAlong", "MorphstampDistance", "MorphstampAddPoints", "MorphstampAlign", "MorphstampPath"),
        "foiltilt" to listOf("StyleFoiltilt", "locate", "FoiltiltAngles"),
        "depthstack" to listOf("StyleDepthstack"),
        "flapcounter" to listOf("StyleFlapcounter", "FlapcounterDigit", "FlapcounterHalf", "FlapcounterFace"),
        "liquidswipe" to listOf("StyleLiquidswipe", "StyleLiquidEdge", "StyleLiquidRevealPath", "StyleLiquidPoster"),
        "elasticnav" to listOf("StyleElasticnav", "nx", "ny"),
        "paperfold" to listOf("StylePaperfold", "settle", "PaperfoldSheet"),
        "scratchmap" to listOf("StyleScratchmap", "scratch", "ScratchmapStroke", "ScratchmapMarkCoverage"),
        "flowtext" to listOf("StyleFlowtext", "FlowtextRun", "FlowtextSlots", "FlowtextLines"),
        "arcchart" to listOf("StyleArcchart", "ArcchartFractions"),
        "typesort" to listOf("StyleTypesort", "TypesortTargetOrder", "TypesortSwapOrder"),
        "depthwheel" to listOf("StyleDepthwheel", "StyleDepthWheelProjection"),
    )

    private fun quoted(value: String): String = "\"" + value.replace("\\", "\\\\")
        .replace("\"", "\\\"").replace("$", "\\$").replace("\n", "\\n") + "\""

    fun build(s: CreativeStyleSpec, p: CreativePattern, references: List<String>, origin: CreativeOrigin?): String {
        val styleArgs = listOf(quoted(s.id), quoted(s.label)) +
            listOf(s.background, s.surface, s.ink, s.accent, s.secondary).map { "0x" + it.toString(16).uppercase() } +
            listOf(s.radius.toString(), s.border.toString(), quoted(s.finish), quoted(s.typography))
        val patternArgs = listOf(p.id, p.title, p.headline, p.caption, p.value, p.action).map(::quoted) +
            "listOf(${p.items.joinToString(", ", transform = ::quoted)})"
        val entry = "Creative" + "${s.id}-${p.id}".split('-').joinToString("") { it.replaceFirstChar(Char::uppercaseChar) }
        return buildString {
            appendLine("// ${s.label} · ${p.title}")
            appendLine(if (origin == null) "// 原创 Compose 演示；复制到已启用 Compose Material3 的 Kotlin 文件。最低 SDK 24。"
                else "// 开源核心的 Compose 最小移植；复制到已启用 Compose Material3 的 Kotlin 文件。最低 SDK 24。")
            appendLine("// 用法：$entry()；示例数据与交互不连接真实业务服务。")
            references.forEach { appendLine("// 设计参考：$it") }
            origin?.let {
                appendLine("// 上游：${it.project} · ${it.repository} · commit ${it.revision}")
                appendLine("// 修改与移植范围：${it.adaptation}")
                appendLine("// 许可：${it.license}；请保留以下完整声明。")
                it.notice.lineSequence().forEach { line -> appendLine("// $line") }
            }
            appendLine(foundation)
            appendLine(layouts.getValue(p.id))
            appendLine("\n@Composable")
            appendLine("fun $entry(modifier: Modifier = Modifier) {")
            appendLine("    val style = CreativeStyleSpec(${styleArgs.joinToString(", ")})")
            appendLine("    val pattern = CreativePattern(${patternArgs.joinToString(", ")})")
            appendLine("    Box(modifier) { ${names.getValue(p.id)}(style, pattern, interactive = true) }")
            appendLine("}")
        }.let { code ->
            // Distinct helper names let independently copied recipes share a package.
            val identifiers = sharedHelpers + localHelpers.getValue(p.id)
            code.replace(Regex("\\b(" + identifiers.joinToString("|") + ")\\b")) { match -> entry + match.value }
        }
    }
}
